    function getDeletedProductIds() {
      let ids = [];
      try {
        ids = JSON.parse(localStorage.getItem("mmo_deleted_product_ids") || "[]");
      } catch(e) { ids = []; }
      if (!Array.isArray(ids)) ids = [];
      return ids.filter(function(id) {
        return typeof id === "string" && id.trim().length > 0;
      });
    }
    window.getDeletedProductIds = getDeletedProductIds;

    function isProductDeleted(productOrId) {
      if (!productOrId) return true;
      const pid = typeof productOrId === "object" ? String(productOrId.id || "").trim() : String(productOrId).trim();
      if (!pid) return true;

      // TUYỆT ĐỐI KHÔNG HIỂN THỊ BẤT KỲ SẢN PHẨM DEMO HOẶC TEST NÀO
      if (pid === "PROD_TEST" || pid.startsWith("SP_") || DUMMY_SEED_IDS.includes(pid)) return true;
      if (typeof productOrId === "object") {
        const pName = String(productOrId.name || "").trim().toLowerCase();
        if (pName === "test" || pName.startsWith("test ") || pName.startsWith("demo ") || pid.toLowerCase().includes("test")) return true;
        if (productOrId.price <= 0 && (!productOrId.variants || productOrId.variants.length === 0)) return true;
      }

      // Đã đánh dấu cờ xóa trực tiếp
      if (typeof productOrId === "object" && productOrId.isDeleted === true) return true;

      // Kiểm tra danh sách đã bị admin xóa
      const deletedIds = getDeletedProductIds();
      if (deletedIds.includes(pid)) return true;
      if (typeof productOrId === "object" && productOrId.name && deletedIds.includes(productOrId.name)) return true;

      return false;
    }
    window.isProductDeleted = isProductDeleted;

    function getVisibleProducts() {
      if (!MOCK_DATA || !Array.isArray(MOCK_DATA.products)) return [];
      const seenIds = new Set();
      const seenNormNames = new Set();
      const result = [];

      for (let i = 0; i < MOCK_DATA.products.length; i++) {
        const p = MOCK_DATA.products[i];
        if (!p || !p.id || isProductDeleted(p)) continue;

        const cleanId = String(p.id).trim();
        if (seenIds.has(cleanId)) continue;

        // Chuẩn hóa tên sản phẩm để loại bỏ triệt để sản phẩm bị trùng lặp (ví dụ Proxy Nhật trùng lặp)
        const rawName = String(p.name || '').trim();
        const normName = rawName.toLowerCase()
          .replace(/[–—−-]/g, '-')
          .replace(/\s+/g, ' ')
          .replace(/[\(\)\[\]]/g, '')
          .trim();

        if (normName && seenNormNames.has(normName)) {
          // Chỉ loại bỏ bản demo SP_ nếu đã có bản PROD_ thật
          const existingIdx = result.findIndex(x => {
            const xn = String(x.name || '').trim().toLowerCase().replace(/[–—−-]/g, '-').replace(/\s+/g, ' ').replace(/[\(\)\[\]]/g, '').trim();
            return xn === normName;
          });
          if (existingIdx !== -1) {
            const existing = result[existingIdx];
            if (existing.id.startsWith("SP_") && !p.id.startsWith("SP_")) {
              result[existingIdx] = p;
              continue;
            }
            if (!existing.id.startsWith("SP_") && p.id.startsWith("SP_")) {
              continue;
            }
            // Nếu cả 2 đều là sản phẩm PROD_ thật với ID khác nhau -> GIỮ NGUYÊN CẢ HAI, TUYỆT ĐỐI KHÔNG XÓA!
          }
        }

        seenIds.add(cleanId);
        if (normName) seenNormNames.add(normName);
        result.push(p);
      }
      return result;
    }
    window.getVisibleProducts = getVisibleProducts;
    // Tự động dọn sạch sản phẩm demo SP_ và loại trừ trùng lặp khỏi localStorage của khách hàng
