    function update2FaUI() {
      const inp = document.getElementById("input2FaSecret");
      const raw = inp ? inp.value.trim() : "";
      const secret = extract2FaSecret(raw);
      const disp = document.getElementById("display2FaCode");
      const timerEl = document.getElementById("display2FaTimer");
      const barEl = document.getElementById("bar2FaCountdown");

      const nowSec = Math.floor(Date.now() / 1000);
      const remaining = 30 - (nowSec % 30);

      if (timerEl) {
        timerEl.innerHTML = "<i class='fa-solid fa-clock'></i> Đổi mã sau: " + remaining + "s";
      }
      if (barEl) {
        const pct = Math.round((remaining / 30) * 100);
        barEl.style.width = pct + "%";
        if (remaining <= 5) {
          barEl.style.background = "#ef4444";
        } else if (remaining <= 10) {
          barEl.style.background = "#f59e0b";
        } else {
          barEl.style.background = "linear-gradient(90deg, #10b981, #f59e0b)";
        }
      }

      if (!secret) {
        if (disp) disp.innerText = "------";
        return;
      }

      const code = generateTOTP(secret, nowSec);
      if (disp) {
        if (code === "ERROR") {
          disp.innerText = "LỖI KEY";
          disp.style.color = "#ef4444";
        } else {
          disp.innerText = code;
          disp.style.color = "#10b981";
        }
      }
    }

    function getLive2FaCode() {
      const inp = document.getElementById("input2FaSecret");
      const raw = inp ? inp.value.trim() : "";
      if (!raw) {
        showToast("Vui lòng nhập 2FA Secret Key (hoặc dán dòng User|Pass|2FA)!", "warning");
        return;
      }
      const secret = extract2FaSecret(raw);
      if (!secret || secret.length < 8) {
        showToast("Mã 2FA Secret Key không hợp lệ!", "danger");
        return;
      }

      update2FaUI();

      if (live2FaInterval) clearInterval(live2FaInterval);
      live2FaInterval = setInterval(update2FaUI, 1000);

      const code = generateTOTP(secret, Math.floor(Date.now() / 1000));
      if (code && code !== "ERROR") {
        showToast("✅ Mã 2FA Google Authenticator: " + code, "success");
      }
    }
    window.getLive2FaCode = getLive2FaCode;

    function handle2FaInput(val) {
      if (!val || !val.trim()) {
        const disp = document.getElementById("display2FaCode");
        if (disp) disp.innerText = "------";
        return;
      }
      const secret = extract2FaSecret(val);
      if (secret && secret.length >= 16) {
        update2FaUI();
        if (!live2FaInterval) {
          live2FaInterval = setInterval(update2FaUI, 1000);
        }
      }
    }
    window.handle2FaInput = handle2FaInput;

