    function runBatch2FaGenerator() {
      const inp = document.getElementById("input2FaBatchList");
      const text = inp ? inp.value.trim() : "";
      if (!text) {
        showToast("Vui lòng dán danh sách tài khoản hoặc mã Secret 2FA!", "warning");
        return;
      }
      const lines = text.split("\n").filter(l => l.trim().length > 0);
      const nowSec = Math.floor(Date.now() / 1000);
      let count = 0;

      const results = lines.map(line => {
        const trimmed = line.trim();
        const secret = extract2FaSecret(trimmed);
        if (!secret) return trimmed + " | [LỖI KEY]";
        const code = generateTOTP(secret, nowSec);
        if (code !== "ERROR") count++;
        return trimmed + " | " + code;
      }).join("\n");

      const out = document.getElementById("output2FaBatch");
      if (out) out.value = results;
      showToast("⚡ Đã tạo mã 2FA chuẩn Google Authenticator cho " + count + "/" + lines.length + " tài khoản!", "success");
    }
    window.runBatch2FaGenerator = runBatch2FaGenerator;

