    // =========================================================================
    // OFFICIAL GOOGLE SIGN-IN SYSTEM (GIS & OAUTH2 POPUP)
    // =========================================================================
    function getGoogleClientId() {
      const sys = typeof getGeneralSettings === "function" ? getGeneralSettings() : {};
      return (sys && sys.googleClientId ? sys.googleClientId.trim() : "") || "788131580065-qev157n8l1422785caijnksf16rg1rq3.apps.googleusercontent.com";
    }

    function initGoogleAuth() {
      try {
        const clientId = getGoogleClientId();
        if (window.google && window.google.accounts && window.google.accounts.id) {
          google.accounts.id.initialize({
            client_id: clientId,
            callback: handleGoogleCredentialResponse,
            auto_select: false,
            cancel_on_tap_outside: true
          });

          const gDiv = document.getElementById("googleOfficialBtn");
          if (gDiv) {
            gDiv.innerHTML = "";
            google.accounts.id.renderButton(gDiv, {
              theme: "outline",
              size: "large",
              type: "standard",
              shape: "rectangular",
              text: "signin_with",
              logo_alignment: "left",
              width: 360
            });
            gDiv.style.display = "flex";
            const customBtn = document.getElementById("btnGoogleCustom");
            if (customBtn) customBtn.style.display = "none";
          }
        }
      } catch(e) {
        console.warn("initGoogleAuth error:", e);
      }
    }
    window.initGoogleAuth = initGoogleAuth;

    function triggerGoogleSignIn() {
      const clientId = getGoogleClientId();

      // 1. Nếu Google GIS có OAuth2, mở Popup Google chính thức để chọn tài khoản
      if (window.google && window.google.accounts && window.google.accounts.oauth2) {
        try {
          const client = google.accounts.oauth2.initTokenClient({
            client_id: clientId,
            scope: "email profile openid",
            callback: async (tokenResponse) => {
              if (tokenResponse && tokenResponse.access_token) {
                showToast("⏳ Đang đồng bộ tài khoản Google...", "info");
                try {
                  const res = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
                    headers: { Authorization: "Bearer " + tokenResponse.access_token }
                  });
                  const profile = await res.json();
                  if (profile && profile.email) {
                    await completeGoogleLogin(profile.email, profile.name, profile.picture);
                  }
                } catch(fetchErr) {
                  console.error("Userinfo fetch error:", fetchErr);
                  showToast("Lỗi lấy thông tin Google!", "danger");
                }
              }
            }
          });
          client.requestAccessToken();
          return;
        } catch(oauthErr) {
          console.warn("Google OAuth2 popup error:", oauthErr);
        }
      }

      // 2. Thử Google GIS One Tap / Account Picker
      if (window.google && window.google.accounts && window.google.accounts.id) {
        try {
          google.accounts.id.initialize({
            client_id: clientId,
            callback: handleGoogleCredentialResponse,
            auto_select: false
          });
          google.accounts.id.prompt();
          return;
        } catch(gErr) {
          console.warn("GIS prompt error:", gErr);
        }
      }

      showToast("Đang kết nối dịch vụ Google, vui lòng thử lại!", "warning");
    }
    window.triggerGoogleSignIn = triggerGoogleSignIn;

    function handleGoogleCredentialResponse(response) {
      if (!response || !response.credential) return;
      const payload = decodeGoogleJwt(response.credential);
      if (payload && payload.email) {
        completeGoogleLogin(payload.email, payload.name, payload.picture);
      }
    }
    window.handleGoogleCredentialResponse = handleGoogleCredentialResponse;

    function decodeGoogleJwt(token) {
      try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        return JSON.parse(jsonPayload);
      } catch(e) {
        return null;
      }
    }
    window.decodeGoogleJwt = decodeGoogleJwt;

    async function completeGoogleLogin(email, name, picture) {
      try {
        if (!email || !email.includes("@")) {
          showToast("Email không hợp lệ!", "warning");
          return;
        }
        email = email.trim().toLowerCase();

        // KIỂM TRA TÀI KHOẢN CÓ ĐANG BỊ KHÓA DO GIAN LẬN KHÔNG TỪ CLOUD TURSO DATABASE
        const isLockedCloud = await checkUserLockedFromCloud(email);
        if (isLockedCloud) {
          closeModal("authModal");
          forceLogoutLockedUser(email);
          return;
        }

        // Check if this email exists in registered members to preserve proper name and balance
        let users = getRegisteredUsers();
        const existingIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === email);
        const existingUser = existingIdx !== -1 ? users[existingIdx] : null;
        if (existingUser) {
          existingUser.isLocked = false;
          existingUser.status = "ACTIVE";
        }

        name = name || (existingUser && existingUser.name) || email.split("@")[0];
        picture = picture || (existingUser && existingUser.avatar) || ("https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email));

        const isAdm = (typeof isAdminUser === "function") ? isAdminUser({ email: email }) : (email === ROOT_ADMIN_EMAIL.toLowerCase());
        const role = isAdm ? "Quản Trị Viên" : ((existingUser && existingUser.role) || "Thành Viên");
        const initBalance = (existingUser && existingUser.balance !== undefined) ? Number(existingUser.balance) : 0;

        // Instant session
        currentUser = {
          userId: (existingUser && existingUser.userId) || ("USR_" + Math.floor(100000 + Math.random() * 900000)),
          name: name,
          email: email,
          role: role,
          balance: initBalance,
          avatar: picture
        };

        // Bind affiliate referrer if available
        const savedRefCode = (localStorage.getItem("mmo_ref_code") || sessionStorage.getItem("mmo_ref_code") || "").trim().toLowerCase();
        if (savedRefCode && savedRefCode !== email && savedRefCode !== email.split("@")[0]) {
          currentUser.referredBy = (existingUser && existingUser.referredBy) ? existingUser.referredBy : savedRefCode;
          if (typeof syncAffiliateRegistrationToCloud === "function" && currentUser.referredBy) {
            syncAffiliateRegistrationToCloud(email, name, currentUser.referredBy, "GOOGLE");
          }
        }

        if (existingIdx !== -1) {
          users[existingIdx] = Object.assign({}, users[existingIdx], currentUser);
        } else {
          users.unshift(Object.assign({}, currentUser, { created: new Date().toLocaleDateString("vi-VN") }));
        }

        saveRegisteredUsers(users);
        localStorage.setItem("mmo_user", JSON.stringify(currentUser));

        closeModal("authModal");
        updateUserUI();

        showToast("🎉 Đăng nhập thành công tài khoản Google: " + (currentUser.name || email), "success");
        if ((isAdm || role === "Quản Trị Viên") && typeof switchView === "function") {
          switchView("viewAdmin");
        }

        // Real-time Cloud sync to Google Sheet in background (safe non-blocking)
        if (typeof callGasApi === "function") {
          callGasApi("authGoogle", {
            email: currentUser.email,
            name: currentUser.name,
            avatar: currentUser.avatar,
            picture: currentUser.avatar,
            role: currentUser.role
          }).then(function(res) {
            if (res && res.success && res.user) {
              if (res.user.is_locked || res.user.isLocked || res.user.status === "LOCKED") {
                forceLogoutLockedUser(email);
                return;
              }
              currentUser.userId = res.user.userId || currentUser.userId;
              if (res.user.balance !== undefined) {
                currentUser.balance = Number(res.user.balance);
              }
              if (res.user.role === "ADMIN") {
                currentUser.role = "Quản Trị Viên";
              }
              localStorage.setItem("mmo_user", JSON.stringify(currentUser));
              let latestUsers = getRegisteredUsers();
              const idx = latestUsers.findIndex(u => (u.email || "").toLowerCase().trim() === email);
              if (idx !== -1) {
                latestUsers[idx].userId = currentUser.userId;
                latestUsers[idx].balance = currentUser.balance;
                latestUsers[idx].role = currentUser.role;
                saveRegisteredUsers(latestUsers);
              }
              updateUserUI();
            }
          }).catch(function(gasErr) {
            console.warn("GAS Google Auth sync note:", gasErr);
          });
        }

      } catch(err) {
        console.error("completeGoogleLogin error:", err);
        showToast("Lỗi đăng nhập Google: " + (err.message || "Vui lòng thử lại!"), "danger");
      }
    }
    window.completeGoogleLogin = completeGoogleLogin;

    async function handleAccountLogin() {
      const email = document.getElementById("loginEmailInput")?.value.trim().toLowerCase();
      const pass = document.getElementById("loginPassInput")?.value;

      if (!email || !email.includes("@")) {
        showToast("Vui lòng nhập địa chỉ email hợp lệ!", "warning");
        return;
      }
      if (!pass) {
        showToast("Vui lòng nhập mật khẩu!", "warning");
        return;
      }

      showToast("⏳ Đang xác thực đăng nhập...", "info");

      // KIỂM TRA TÀI KHOẢN CÓ ĐANG BỊ KHÓA DO GIAN LẬN KHÔNG TỪ CLOUD TURSO DATABASE
      const isLockedCloud = await checkUserLockedFromCloud(email);
      if (isLockedCloud) {
        closeModal("authModal");
        forceLogoutLockedUser(email);
        return;
      }

      const isAdm = (typeof isAdminUser === "function") ? isAdminUser({ email: email }) : false;
      const role = isAdm ? "Quản Trị Viên" : "MEMBER";

      // Instant local check
      let users = getRegisteredUsers();
      const found = users.find(u => (u.email || "").toLowerCase().trim() === email);
      if (found) {
        found.isLocked = false;
        found.status = "ACTIVE";
      }

      const savedRefCode = (localStorage.getItem("mmo_ref_code") || sessionStorage.getItem("mmo_ref_code") || "").trim().toLowerCase();
      let refToAssign = "";
      if (savedRefCode && savedRefCode !== email && savedRefCode !== email.split("@")[0]) {
        refToAssign = savedRefCode;
      }

      currentUser = {
        userId: found?.userId || ("USR_" + Math.floor(100000 + Math.random() * 900000)),
        name: found?.name || (isAdm ? "Quản Trị Viên (Admin)" : email.split("@")[0]),
        email: email,
        role: isAdm ? "Quản Trị Viên" : (found?.role || role),
        balance: found?.balance !== undefined ? found.balance : 0,
        avatar: found?.avatar || ("https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email)),
        referredBy: found?.referredBy || refToAssign
      };

      if (!found) {
        users.unshift(currentUser);
        saveRegisteredUsers(users);
      }

      localStorage.setItem("mmo_user", JSON.stringify(currentUser));
      updateUserUI();
      closeModal("authModal");
      showToast("🎉 Đăng nhập thành công! Chào mừng " + (currentUser.name || currentUser.email), "success");
      if (isAdm && typeof switchView === "function") {
        switchView("viewAdmin");
      } else {
        switchView("viewProfile");
        switchProfileTab("tabProfWallet");
      }

      // Background GAS call
      if (typeof callGasApi === "function") {
        callGasApi("login", { mode: "login", action: "login", email: email, password: pass }).then(function(res) {
          if (res && res.success && res.user) {
            currentUser.userId = res.user.userId || currentUser.userId;
            if (res.user.balance !== undefined) {
              currentUser.balance = Number(res.user.balance);
            }
            if (res.user.role === "ADMIN") {
              currentUser.role = "Quản Trị Viên";
            }
            localStorage.setItem("mmo_user", JSON.stringify(currentUser));
            let latestUsers = getRegisteredUsers();
            const idx = latestUsers.findIndex(u => (u.email || "").toLowerCase().trim() === email);
            if (idx !== -1) {
              latestUsers[idx].userId = currentUser.userId;
              latestUsers[idx].balance = currentUser.balance;
              latestUsers[idx].role = currentUser.role;
              saveRegisteredUsers(latestUsers);
            }
            updateUserUI();
          }
        }).catch(function(e) {});
      }
    }
    window.handleAccountLogin = handleAccountLogin;

    async function registerNewAccount() {
      const name = document.getElementById("regNameInput")?.value.trim();
      const email = document.getElementById("regEmailInput")?.value.trim().toLowerCase();
      const pass = document.getElementById("regPassInput")?.value;
      const passConfirm = (document.getElementById("regConfirmPassInput") || document.getElementById("regPassConfirmInput"))?.value;

      if (!name) {
        showToast("Vui lòng nhập Họ & Tên!", "warning");
        return;
      }
      if (!email || !email.includes("@")) {
        showToast("Vui lòng nhập email hợp lệ!", "warning");
        return;
      }
      if (!pass || pass.length < 6) {
        showToast("Mật khẩu phải có ít nhất 6 ký tự!", "warning");
        return;
      }
      if (pass !== passConfirm) {
        showToast("Mật khẩu xác nhận không khớp!", "warning");
        return;
      }

      const existingUsers = getRegisteredUsers();
      if (existingUsers.some(u => (u.email || "").toLowerCase().trim() === email)) {
        showToast("⚠️ Email này đã được đăng ký! Vui lòng Đăng Nhập hoặc dùng Quên Mật Khẩu.", "warning");
        if (typeof switchAuthTab === "function") switchAuthTab("login");
        return;
      }

      const savedRefCode = (localStorage.getItem("mmo_ref_code") || sessionStorage.getItem("mmo_ref_code") || "").trim().toLowerCase();
      let refToAssign = "";
      if (savedRefCode && savedRefCode !== email && savedRefCode !== email.split("@")[0]) {
        refToAssign = savedRefCode;
      }

      const isAdm = (typeof isAdminUser === "function") ? isAdminUser({ email: email }) : false;
      const role = isAdm ? "Quản Trị Viên" : "MEMBER";

      // 1. TẠO TÀI KHOẢN TỨC THÌ (0ms) - TUYỆT ĐỐI KHÔNG LÀM ĐƠ/TREO TRÌNH DUYỆT CỦA KHÁCH
      currentUser = {
        userId: "USR_" + Math.floor(100000 + Math.random() * 900000),
        name: name,
        email: email,
        role: role,
        balance: 0,
        avatar: "https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email),
        referredBy: refToAssign,
        created: new Date().toLocaleDateString("vi-VN")
      };

      const users = getRegisteredUsers();
      if (!users.some(u => (u.email || "").toLowerCase().trim() === email)) {
        users.push(currentUser);
        saveRegisteredUsers(users);
      }

      localStorage.setItem("mmo_user", JSON.stringify(currentUser));
      updateUserUI();
      closeModal("authModal");
      showToast("🎉 Đăng ký tài khoản thành công! Chào mừng " + name, "success");
      switchView("viewProfile");

      // 2. GHI NHẬN THÀNH VIÊN F1 LÊN CLOUD WORKER TURSO & PHÁT SÓNG REALTIME
      if (refToAssign && typeof syncAffiliateRegistrationToCloud === "function") {
        syncAffiliateRegistrationToCloud(email, name, refToAssign, "EMAIL");
      }

      // 3. ĐỒNG BỘ GOOGLE APPS SCRIPT CHẠY NGẦM TRONG NỀN (NON-BLOCKING)
      if (typeof callGasApi === "function") {
        callGasApi("register", {
          mode: "register",
          action: "register",
          name: name,
          email: email,
          password: pass,
          referredBy: refToAssign
        }).then(function(res) {
          if (res && res.success && res.user && res.user.userId) {
            currentUser.userId = res.user.userId;
            localStorage.setItem("mmo_user", JSON.stringify(currentUser));
            let latestUsers = getRegisteredUsers();
            const idx = latestUsers.findIndex(u => (u.email || "").toLowerCase().trim() === email);
            if (idx !== -1) {
              latestUsers[idx].userId = currentUser.userId;
              saveRegisteredUsers(latestUsers);
            }
          }
        }).catch(function(e) {
          console.warn("Background GAS registration note:", e);
        });
      }
    }
    window.registerNewAccount = registerNewAccount;
    window.handleAccountRegister = registerNewAccount;

    function logoutUser() {
      currentUser = null;
      localStorage.removeItem("mmo_user");
      localStorage.setItem("mmo_current_view", "viewStore");
      updateUserUI();
      switchView("viewStore");
      showToast("👋 Đã đăng xuất tài khoản thành công!", "info");
    }

    function switchProfileTab(tabId) {
      if (!tabId) tabId = "tabProfWallet";
      localStorage.setItem("mmo_profile_tab", tabId);

      const sections = ["tabProfWallet", "tabProfOrders", "tabProfInfo", "tabProfBank", "tabProfAffiliate", "tabProfNotify", "tabProfWishlist", "tabProfApi"];
      sections.forEach(sId => {
        const el = document.getElementById(sId);
        if (el) el.style.display = "none";
      });

      const buttons = ["tabBtnProfWallet", "tabBtnProfOrders", "tabBtnProfInfo", "tabBtnProfBank", "tabBtnProfAffiliate", "tabBtnProfNotify", "tabBtnProfWishlist", "tabBtnProfApi"];
      buttons.forEach(bId => {
        const btn = document.getElementById(bId);
        if (btn) btn.classList.remove("active");
      });

      const targetSec = document.getElementById(tabId);
      if (targetSec) targetSec.style.display = "block";

      const targetBtn = document.getElementById(tabId.startsWith("tab") ? "tabBtn" + tabId.substring(3) : tabId) || document.querySelector(`[onclick*="${tabId}"]`);
      if (targetBtn) targetBtn.classList.add("active");

      if (tabId === "tabProfWallet") {
        if (typeof renderUserWalletTransactions === "function") renderUserWalletTransactions();
        if (typeof renderUserBalanceLogs === "function") renderUserBalanceLogs();
        if (typeof renderUserWalletStats === "function") renderUserWalletStats();
        if (typeof loadUserWalletFromCloud === "function") loadUserWalletFromCloud();
      } else if (tabId === "tabProfOrders") {
        if (typeof renderProfileOrders === "function") renderProfileOrders();
        if (typeof syncCloudOrdersToLocalUI === "function") syncCloudOrdersToLocalUI(true);
      } else if (tabId === "tabProfInfo") {
        if (typeof populateProfileInfoInputs === "function") populateProfileInfoInputs();
      } else if (tabId === "tabProfAffiliate") {
        if (typeof renderAffiliateDashboard === "function") renderAffiliateDashboard();
      }
    }

