    function getRealisticProductSold(p) {
      if (!p) return 0;
      const PRESET_SOLD = {
        'PROD_MTQX465U': 3420, // Gmail cho Thuê 10 phút live 10 phút
        'PROD_MTQQXO2E': 2180, // Gmail cho Thuê 24h
        'PROD_MTQX1C7X': 1650, // Gmail cho thuê 1 giờ live 60 phút
        'PROD_MTQWMPL5': 890,  // Gmail cho thuê 7 Ngày
        'PROD_MTQX7SIK': 640,  // Gmail Cho Thuê 14 Ngày live 14 ngày
        'PROD_MTQWQFZD': 480,  // Gmail cho thuê 30 Ngày
        'PROD_MTQZT2Y1': 2850, // HOTMAIL ĐỘ TRUST CAO LIVE TRÂU
        'PROD_MTRB6000': 1920, // OUTLOOK TRUSTED - LIVE 6-12 Tháng
        'PROD_MTPIJ9XV': 1270, // TÀI KHOẢN TIKTOK BRAZIL ĐÃ NGÂM LÂU - CỰ KỲ TRÂU
        'PROD_MTPI7PIO': 156,  // NHÓM ZALO NEW 2016
        'PROD_MU1LSSJ7AZ': 520,
        'PROD_MU1G6LJX': 180
      };
      const pid = String(p.id || '').trim();
      if (PRESET_SOLD[pid]) return PRESET_SOLD[pid];

      const pName = (p.name || '').toLowerCase();
      if (pName.includes('10 phut') || pName.includes('10 phút')) return 3420;
      if (pName.includes('24h') && pName.includes('gmail')) return 2180;
      if (pName.includes('1 gio') || pName.includes('1 giờ') || pName.includes('60 phut') || pName.includes('60 phút')) return 1650;
      if (pName.includes('7 ngay') || pName.includes('7 ngày')) return 890;
      if (pName.includes('14 ngay') || pName.includes('14 ngày')) return 640;
      if (pName.includes('30 ngay') || pName.includes('30 ngày')) return 480;
      if (pName.includes('hotmail') && (pName.includes('trust') || pName.includes('trau') || pName.includes('trâu'))) return 2850;
      if (pName.includes('outlook') && pName.includes('trust')) return 1920;
      if (pName.includes('tiktok') && (pName.includes('brazil') || pName.includes('ngam') || pName.includes('ngâm'))) return 1270;
      if (pName.includes('zalo')) return 156;

      const s = (p.buffSold !== undefined && p.buffSold !== null && Number(p.buffSold) !== 100) 
        ? Number(p.buffSold) 
        : (p.sold !== undefined && p.sold !== null && Number(p.sold) !== 100 ? Number(p.sold) : null);
      if (s !== null && !isNaN(s) && s > 0) return s;

      let h = 0;
      const str = pid + (p.name || '');
      for (let c = 0; c < str.length; c++) h = (h * 31 + str.charCodeAt(c)) & 0x7FFFFFFF;
      const price = Number(p.price) || 0;
      if (price <= 500) return 1200 + (h % 2200);
      if (price <= 5000) return 700 + (h % 1300);
      if (price <= 20000) return 400 + (h % 600);
      if (price <= 100000) return 180 + (h % 350);
      return 85 + (h % 250);
    }
    window.getRealisticProductSold = getRealisticProductSold;

    // =========================================================================
    // RENDER PRODUCT DETAIL SIDEBARS (PHÂN BIỆT 100% 2 THANH BÊN KHÔNG TRÙNG LẶP)
    // - Thanh Trái (#detailLeftBestList): Top 10 Bán chạy nhất toàn sàn (loại trừ SP đang xem)
    // - Thanh Phải (#detailRightRecList): Top 10 Đề xuất theo ngữ cảnh (Proxy, Mail, Tool...) 
    //   và TUYỆT ĐỐI KHÔNG TRÙNG LẶP BẤT KỲ SẢN PHẨM NÀO VỚI THANH BÊN TRÁI
    // =========================================================================
    function renderProductDetailSidebars(currentProd) {
      const dtlLeft = document.getElementById("detailLeftBestList");
      const dtlRight = document.getElementById("detailRightRecList");
      if (!dtlLeft && !dtlRight) return;

      const prods = (typeof getVisibleProducts === "function") 
        ? getVisibleProducts() 
        : ((typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) ? [...MOCK_DATA.products] : []);
      if (!prods || prods.length === 0) return;

      if (currentProd) {
        window._currentActiveDetailProduct = currentProd;
      } else if (window._currentActiveDetailProduct) {
        currentProd = window._currentActiveDetailProduct;
      }

      const curId = currentProd ? String(currentProd.id).trim() : null;

      function renderCompactItemHtml(p) {
        if (!p) return "";
        const displaySold = (typeof getRealisticProductSold === "function") 
          ? getRealisticProductSold(p).toLocaleString("vi-VN") 
          : (p.buffSold || p.sold || 0);
        const imgUrl = (typeof resolveProductImage === "function") 
          ? resolveProductImage(p) 
          : (p.image || p.image_url || '');
        const priceDisplay = (typeof getProductPriceDisplay === "function") 
          ? getProductPriceDisplay(p) 
          : (typeof formatVND === "function" ? formatVND(p.price) : (p.price + " đ"));
        const pIdEscaped = (typeof escapeHtml === "function") ? escapeHtml(p.id) : p.id;
        const pNameEscaped = (typeof escapeHtml === "function") ? escapeHtml(p.name) : p.name;
        
        return '<div class="compact-product-item" onclick="openProductDetailById(\'' + pIdEscaped + '\')">' +
          '<div class="compact-thumb"><img src="' + imgUrl + '" alt="' + pNameEscaped + '" loading="lazy" onerror="this.onerror=null; this.src=\'https://iili.io/nFV4Rln.png\';" /></div>' +
          '<div class="compact-info">' +
            '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" class="compact-title" onclick="if(!event.ctrlKey && !event.metaKey && event.button === 0){ event.preventDefault(); event.stopPropagation(); openProductDetailById(\'' + pIdEscaped + '\'); }" style="text-decoration:none; color:inherit; display:block;">' + pNameEscaped + '</a>' +
            '<div class="compact-meta">' +
              '<span class="compact-price">' + priceDisplay + '</span>' +
              '<span class="compact-sold">Đã bán: ' + displaySold + '</span>' +
            '</div>' +
          '</div>' +
        '</div>';
      }

      function normProdTitle(name) {
        return String(name || '').toLowerCase()
          .replace(/[–—−-]/g, '-')
          .replace(/\s+/g, ' ')
          .replace(/[\(\)\[\]]/g, '')
          .trim();
      }

      const curNormTitle = currentProd ? normProdTitle(currentProd.name) : null;

      // 1. THANH BÊN TRÁI: "SẢN PHẨM NỔI BẬT" (Top bán chạy nhất toàn sàn, loại trừ SP đang xem)
      const leftCandidates = prods.filter(p => {
        if (!p || !p.id) return false;
        if (curId && String(p.id).trim() === curId) return false;
        if (curNormTitle && normProdTitle(p.name) === curNormTitle) return false;
        return true;
      });
      leftCandidates.sort((a, b) => {
        const soldA = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(a) : (a.buffSold || a.sold || 0);
        const soldB = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(b) : (b.buffSold || b.sold || 0);
        return soldB - soldA;
      });

      const leftItems = [];
      const leftIds = new Set();
      const leftTitles = new Set();
      if (curId) leftIds.add(curId);
      if (curNormTitle) leftTitles.add(curNormTitle);

      for (let i = 0; i < leftCandidates.length && leftItems.length < 10; i++) {
        const item = leftCandidates[i];
        const t = normProdTitle(item.name);
        if (t && leftTitles.has(t)) continue; // Loại trừ sản phẩm trùng tên!
        leftItems.push(item);
        leftIds.add(String(item.id).trim());
        if (t) leftTitles.add(t);
      }

      if (dtlLeft) {
        dtlLeft.innerHTML = leftItems.map(renderCompactItemHtml).join("");
      }

      // 2. THANH BÊN PHẢI: "SẢN PHẨM ĐỀ XUẤT" (KHÔNG TRÙNG LẶP 100% VỚI THANH TRÁI & SP ĐANG XEM)
      const rightCandidates = prods.filter(p => {
        if (!p || !p.id) return false;
        if (leftIds.has(String(p.id).trim())) return false;
        const t = normProdTitle(p.name);
        if (t && leftTitles.has(t)) return false; // Loại trừ sản phẩm đã có ở thanh trái hoặc trùng sản phẩm đang xem
        return true;
      });

      const curCategory = currentProd ? String(currentProd.category || currentProd.cate || "").toLowerCase() : "";
      const curNameLower = currentProd ? String(currentProd.name || "").toLowerCase() : "";

      // Nhận diện nhóm ngành ngữ cảnh của sản phẩm đang xem
      const isProxy = curNameLower.includes("proxy") || curCategory.includes("proxy");
      const isMail = curNameLower.includes("mail") || curNameLower.includes("gmail") || curNameLower.includes("outlook") || curNameLower.includes("hotmail") || curCategory.includes("mail") || curCategory.includes("gmail");
      const isSocial = curNameLower.includes("tiktok") || curNameLower.includes("facebook") || curNameLower.includes("fb") || curNameLower.includes("via") || curNameLower.includes("clone") || curCategory.includes("tiktok") || curCategory.includes("facebook");
      const isSoftwareAi = curNameLower.includes("kling") || curNameLower.includes("chatgpt") || curNameLower.includes("canva") || curNameLower.includes("netflix") || curNameLower.includes("capcut") || curNameLower.includes("ai") || curCategory.includes("ai") || curCategory.includes("phan mem");

      rightCandidates.sort((a, b) => {
        let scoreA = 0;
        let scoreB = 0;

        const aName = String(a.name || "").toLowerCase();
        const bName = String(b.name || "").toLowerCase();
        const aCat = String(a.category || "").toLowerCase();
        const bCat = String(b.category || "").toLowerCase();

        // Điểm cùng danh mục
        if (curCategory && aCat === curCategory) scoreA += 60;
        if (curCategory && bCat === curCategory) scoreB += 60;

        // Điểm cùng nhóm ngành liên quan
        if (isProxy) {
          if (aName.includes("proxy") || aCat.includes("proxy")) scoreA += 50;
          if (bName.includes("proxy") || bCat.includes("proxy")) scoreB += 50;
        } else if (isMail) {
          if (aName.includes("mail") || aName.includes("gmail") || aName.includes("outlook") || aName.includes("hotmail") || aCat.includes("mail")) scoreA += 50;
          if (bName.includes("mail") || bName.includes("gmail") || bName.includes("outlook") || bName.includes("hotmail") || bCat.includes("mail")) scoreB += 50;
        } else if (isSocial) {
          if (aName.includes("tiktok") || aName.includes("fb") || aName.includes("via") || aName.includes("clone") || aCat.includes("tiktok") || aCat.includes("facebook")) scoreA += 50;
          if (bName.includes("tiktok") || bName.includes("fb") || bName.includes("via") || bName.includes("clone") || bCat.includes("tiktok") || bCat.includes("facebook")) scoreB += 50;
        } else if (isSoftwareAi) {
          if (aName.includes("ai") || aName.includes("canva") || aName.includes("chatgpt") || aName.includes("kling") || aName.includes("capcut") || aCat.includes("ai")) scoreA += 50;
          if (bName.includes("ai") || bName.includes("canva") || bName.includes("chatgpt") || bName.includes("kling") || bCat.includes("capcut") || bCat.includes("ai")) scoreB += 50;
        }

        // Ưu tiên sản phẩm còn hàng
        const stockA = (typeof getProductStockCount === "function") ? getProductStockCount(a) : (a.stock !== undefined ? a.stock : 10);
        const stockB = (typeof getProductStockCount === "function") ? getProductStockCount(b) : (b.stock !== undefined ? b.stock : 10);
        if (stockA > 0) scoreA += 25;
        if (stockB > 0) scoreB += 25;

        // Điểm đánh giá (Rating)
        const ratingA = Number(a.rating) || 5;
        const ratingB = Number(b.rating) || 5;
        scoreA += ratingA * 3;
        scoreB += ratingB * 3;

        // Điểm phổ biến (Sales)
        const soldA = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(a) : (a.buffSold || a.sold || 0);
        const soldB = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(b) : (b.buffSold || b.sold || 0);
        scoreA += Math.min(20, Math.floor(soldA / 50));
        scoreB += Math.min(20, Math.floor(soldB / 50));

        return scoreB - scoreA;
      });

      const rightItems = [];
      const rightTitles = new Set();
      for (let i = 0; i < rightCandidates.length && rightItems.length < 10; i++) {
        const item = rightCandidates[i];
        const t = normProdTitle(item.name);
        if (t && (rightTitles.has(t) || leftTitles.has(t))) continue;
        rightItems.push(item);
        if (t) rightTitles.add(t);
      }

      if (dtlRight) {
        dtlRight.innerHTML = rightItems.map(renderCompactItemHtml).join("");
      }
    }
    window.renderProductDetailSidebars = renderProductDetailSidebars;

    // RENDER BEST SELLERS (LEFT SIDEBAR & DETAIL SIDEBAR)
    function renderBestSellers() {
      const list = document.getElementById("bestSellerList");
      const dtlLeft = document.getElementById("detailLeftBestList");
      if (!list && !dtlLeft) return;

      const prods = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? [...MOCK_DATA.products] : []);
      prods.sort((a, b) => {
        const soldA = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(a) : (a.buffSold || a.sold || 0);
        const soldB = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(b) : (b.buffSold || b.sold || 0);
        return soldB - soldA;
      });

      const items = prods.slice(0, 12);
      const html = items.map(function(p) {
        const displaySold = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(p).toLocaleString("vi-VN") : (p.buffSold || p.sold || 0);
        const imgUrl = (typeof resolveProductImage === "function") ? resolveProductImage(p) : (p.image || '');
        return '<div class="compact-product-item" onclick="openProductDetailById(\'' + p.id + '\')">' +
          '<div class="compact-thumb"><img src="' + imgUrl + '" alt="' + escapeHtml(p.name) + '" loading="lazy" /></div>' +
          '<div class="compact-info">' +
            '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" class="compact-title" onclick="if(!event.ctrlKey && !event.metaKey && event.button === 0){ event.preventDefault(); event.stopPropagation(); openProductDetailById(\'' + p.id + '\'); }" style="text-decoration:none; color:inherit; display:block;">' + escapeHtml(p.name) + '</a>' +
            '<div class="compact-meta">' +
              '<span class="compact-price">' + ((typeof getProductPriceDisplay === "function") ? getProductPriceDisplay(p) : formatVND(p.price)) + '</span>' +
              '<span class="compact-sold">Đã bán: ' + displaySold + '</span>' +
            '</div>' +
          '</div>' +
        '</div>';
      }).join("");

      if (list) list.innerHTML = html;
      if (dtlLeft) {
        renderProductDetailSidebars(window._currentActiveDetailProduct || null);
      }
    }

    // RENDER RECOMMENDED (TRANG CHỦ: ĐÚNG 1 HÀNG 6 SẢN PHẨM LUÂN PHIÊN; TRANG CHI TIẾT: PHÂN BIỆT 100%)
    let _recRotationIndex = 0;
    try {
      _recRotationIndex = parseInt(sessionStorage.getItem("mmo_rec_rot_idx") || "0", 10) || 0;
      sessionStorage.setItem("mmo_rec_rot_idx", String(_recRotationIndex + 6));
    } catch(e) {}

    function renderRecommended() {
      const grid = document.getElementById("recommendedGrid");
      const dtlRight = document.getElementById("detailRightRecList");
      if (!grid && !dtlRight) return;

      const prods = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? [...MOCK_DATA.products] : []);
      if (!prods || prods.length === 0) return;
      
      function getProdStock(p) {
        if (typeof getProductStockCount === "function") {
          return getProductStockCount(p);
        }
        if (p.variants && p.variants.length > 0) {
          return p.variants.reduce((sum, v) => sum + (v.stock !== undefined ? v.stock : 99), 0);
        }
        return (p.stock !== undefined ? p.stock : 99);
      }

      function getProductPopularityScore(p) {
        const sold = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(p) : (p.buffSold || p.sold || 0);
        let views = 0;
        if (typeof p.views === "number" && !isNaN(p.views)) {
          views = p.views;
        } else if (typeof p.views === "string") {
          const numMatch = p.views.match(/[0-9.]+/);
          if (numMatch) {
            let v = parseFloat(numMatch[0]);
            if (p.views.toLowerCase().includes("k")) v *= 1000;
            views = v;
          }
        }
        return (sold * 10) + views;
      }

      let sortedProds = [...prods].sort((a, b) => {
        const hasA = getProdStock(a) > 0 ? 1 : 0;
        const hasB = getProdStock(b) > 0 ? 1 : 0;
        if (hasA !== hasB) return hasB - hasA;
        const scoreA = getProductPopularityScore(a);
        const scoreB = getProductPopularityScore(b);
        return scoreB - scoreA;
      });

      // TRANG CHỦ: CHỈ HIỂN THỊ ĐÚNG 1 HÀNG 6 SẢN PHẨM & LUÂN PHIÊN TOÀN BỘ SẢN PHẨM
      if (grid) {
        const REC_ROW_COUNT = 6;
        const total = sortedProds.length;
        if (total > 0) {
          const startIndex = (_recRotationIndex % total);
          const selectedRecs = [];
          for (let i = 0; i < REC_ROW_COUNT && i < total; i++) {
            selectedRecs.push(sortedProds[(startIndex + i) % total]);
          }
          grid.innerHTML = selectedRecs.map(p => renderSingleCard(p, false)).join("");
        }

        if (typeof window !== "undefined" && !window._recRotationIntervalSet) {
          window._recRotationIntervalSet = true;
          setInterval(function() {
            const rGrid = document.getElementById("recommendedGrid");
            const curV = (typeof currentView !== "undefined") ? currentView : "viewStore";
            if (rGrid && (curV === "viewStore" || !document.getElementById("viewStore")?.classList.contains("hidden"))) {
              _recRotationIndex += 6;
              try { sessionStorage.setItem("mmo_rec_rot_idx", String(_recRotationIndex)); } catch(e) {}
              renderRecommended();
            }
          }, 15000);
        }
      }

      // TRANG CHI TIẾT SẢN PHẨM: ĐỒNG BỘ QUA renderProductDetailSidebars ĐỂ KHÔNG BAO GIỜ TRÙNG LẶP
      if (dtlRight) {
        renderProductDetailSidebars(window._currentActiveDetailProduct || null);
      }
    }
    try { window.renderRecommended = renderRecommended; } catch(e) {}
    function renderSingleCard(p, isSponsored = false) {
      const displaySold = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(p).toLocaleString("vi-VN") : (p.buffSold || p.sold || 0);
      const totalStock = typeof getProductStockCount === "function" ? getProductStockCount(p) : (p.stock !== undefined ? p.stock : 0);
      const isApi = (p.deliveryType === "api" || p.delivery_type === "api") || (typeof isProductApi === "function" && isProductApi(p));

      let stockHtml = '';
      let badgeWarningHtml = '';
      let apiBadgeHtml = '';

      if (totalStock === 0) {
        stockHtml = '<span style="color:#f59e0b; font-weight:700;"><i class="fa-solid fa-clock"></i> Đặt trước</span>';
        badgeWarningHtml = '<span style="position:absolute; top:8px; left:8px; background:linear-gradient(135deg,#f59e0b,#ea580c); color:#fff; font-size:0.68rem; font-weight:700; padding:2px 7px; border-radius:4px; box-shadow:0 2px 6px rgba(0,0,0,0.5); z-index:2;"><i class="fa-solid fa-clock"></i> Đặt trước</span>';
      } else if (totalStock > 0 && totalStock < 5) {
        stockHtml = '<span style="color:#f59e0b; font-weight:700;"><i class="fa-solid fa-triangle-exclamation"></i> Sắp hết (' + totalStock + ')</span>';
        badgeWarningHtml = '<span style="position:absolute; top:8px; left:8px; background:linear-gradient(135deg,#f59e0b,#d97706); color:#fff; font-size:0.68rem; font-weight:700; padding:2px 7px; border-radius:4px; box-shadow:0 2px 6px rgba(0,0,0,0.5); z-index:2;"><i class="fa-solid fa-triangle-exclamation"></i> Sắp hết (' + totalStock + ')</span>';
      } else {
        const displayStockVal = totalStock > 99 ? '99+' : totalStock;
        stockHtml = '<span style="color:#94a3b8;">Kho: ' + displayStockVal + '</span>';
      }

      let cRate = 10;
      if (typeof p.commissionRate === "number" && !isNaN(p.commissionRate)) cRate = p.commissionRate;
      else if (typeof p.commission === "number" && !isNaN(p.commission)) cRate = p.commission <= 1 ? Math.round(p.commission * 100) : p.commission;
      else if (p.commission) {
        const m = String(p.commission).match(/[0-9]+/);
        cRate = m ? parseInt(m[0], 10) : 10;
      }
      if (isNaN(cRate) || cRate <= 0) cRate = 10;
      const cVal = Math.round(Number(p.price || 0) * cRate / 100);
      const commTagHtml = '<div class="product-commission-tag"><i class="fa-solid fa-dollar-sign"></i> <span class="comm-text-full">HOA HỒNG: ' + cRate + '% (~' + (typeof formatVND === "function" ? formatVND(cVal) : cVal.toLocaleString("vi-VN") + ' đ') + ')</span><span class="comm-text-short">HH ' + cRate + '%</span></div>';

      const cardImg = (typeof resolveProductImage === "function") ? resolveProductImage(p) : (p.image || '');
      return '<div class="product-card" onclick="openProductDetailById(\'' + p.id + '\')">' +
        '<div class="product-img-wrap" style="position:relative;">' +
          badgeWarningHtml +
          '<img src="' + cardImg + '" alt="' + escapeHtml(p.name) + '" loading="lazy" onerror="this.onerror=null; this.src=\'https://iili.io/nFV4Rln.png\';" />' +
        '</div>' +
        '<div class="product-body">' +
          '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" class="product-title" onclick="if(!event.ctrlKey && !event.metaKey && event.button === 0){ event.preventDefault(); event.stopPropagation(); openProductDetailById(\'' + p.id + '\'); }" style="text-decoration:none; color:inherit; display:block;" title="' + escapeHtml(p.name) + '">' + escapeHtml(p.name) + '</a>' +
          commTagHtml +
          '<div class="product-footer-row">' +
            '<span class="product-price">' + ((typeof getProductPriceDisplay === "function") ? getProductPriceDisplay(p) : formatVND(p.price)) + '</span>' +
            '<span class="product-rating-pill"><i class="fa-solid fa-star"></i> ' + (p.rating || '4.8') + '</span>' +
          '</div>' +
          '<div class="product-stock-line">' +
            '<span>Đã bán: ' + displaySold + '</span>' +
            stockHtml +
          '</div>' +
        '</div>' +
      '</div>';
    }
    window.renderSingleCard = renderSingleCard;

    // RENDER CATEGORIES
    function renderCategories() {
      const container = document.getElementById("categoryTabs");
      if (!container) return;
      const cats = (MOCK_DATA && MOCK_DATA.categories) ? MOCK_DATA.categories : ["Tất cả"];
      container.innerHTML = cats.map(function(cat) {
        return '<button class="category-pill ' + (cat === currentCategory ? 'active' : '') + '" onclick="filterCategory(\'' + escapeHtml(cat) + '\')">' +
          escapeHtml(cat) +
        '</button>';
      }).join("");
    }

    function filterCategory(cat) {
      currentCategory = cat;
      if (typeof paginationState !== "undefined") paginationState.storeProd = 1;
      const curView = localStorage.getItem("mmo_current_view") || "viewStore";
      if (curView !== "viewStore" && typeof switchView === "function") {
        switchView("viewStore");
      }
      try {
        const url = new URL(window.location.href);
        if (cat && cat !== "Tất cả") {
          url.searchParams.set("category", cat);
        } else {
          url.searchParams.delete("category");
        }
        url.searchParams.delete("prod");
        url.searchParams.delete("product");
        url.searchParams.delete("m");
        const newUrl = url.pathname + (url.searchParams.toString() ? "?" + url.searchParams.toString() : "");
        window.history.replaceState(null, "", newUrl);
      } catch(e) {}
      renderCategories();
      renderProductGrid();
    }
    window.filterCategory = filterCategory;
    window.switchCategory = filterCategory;

    // SMART SEARCH & ACCENT-INSENSITIVE PRODUCT MATCHER
    function matchProductQuery(p, q) {
      if (!p || !q) return false;
      const qRaw = String(q).toLowerCase().trim();
      if (!qRaw) return true;
      const removeAcc = function(s) {
        return String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/Đ/g, "D").toLowerCase().trim();
      };
      const qNorm = removeAcc(qRaw);
      const qCompressed = qNorm.replace(/\s+/g, "");

      const nameRaw = (p.name || "").toLowerCase();
      const nameNorm = removeAcc(nameRaw);
      const nameCompressed = nameNorm.replace(/\s+/g, "");

      const catRaw = (p.category || "").toLowerCase();
      const catNorm = removeAcc(catRaw);
      const catCompressed = catNorm.replace(/\s+/g, "");

      const descRaw = (p.description || "").toLowerCase();
      const descNorm = removeAcc(descRaw);

      // 1. Direct or normalized substring match
      if (nameRaw.includes(qRaw) || nameNorm.includes(qNorm)) return true;
      if (catRaw.includes(qRaw) || catNorm.includes(qNorm)) return true;
      if (descRaw.includes(qRaw) || descNorm.includes(qNorm)) return true;

      // 2. Compressed match (e.g. 'cap cut' matches 'capcut', 'chat gpt' matches 'chatgpt')
      if (nameCompressed.includes(qCompressed) || catCompressed.includes(qCompressed)) return true;

      // 3. Variant names match
      if (Array.isArray(p.variants)) {
        const vMatch = p.variants.some(function(v) {
          if (!v || !v.name) return false;
          const vn = v.name.toLowerCase();
          const vNorm = removeAcc(vn);
          const vComp = vNorm.replace(/\s+/g, "");
          return vn.includes(qRaw) || vNorm.includes(qNorm) || vComp.includes(qCompressed);
        });
        if (vMatch) return true;
      }

      // 4. Multi-word match: all words in query match in name/cat/desc
      const words = qNorm.split(/\s+/).filter(Boolean);
      if (words.length > 1) {
        const fullCombined = nameNorm + " " + catNorm + " " + descNorm;
        if (words.every(function(w) { return fullCombined.includes(w); })) return true;
      }

      return false;
    }
    window.matchProductQuery = matchProductQuery;

    // RENDER PRODUCT GRID WITH 10-ITEM PAGINATION
    function renderProductGrid() {
      const container = document.getElementById("productGrid");
      if (!container) return;

      let filtered = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? [...MOCK_DATA.products] : []);
      if (currentCategory && currentCategory !== "Tất cả") {
        filtered = filtered.filter(function(p) { return (p.category || "").toLowerCase().includes(currentCategory.toLowerCase()); });
      }

      const q = (document.getElementById("searchInput")?.value || "").trim();
      if (q) {
        filtered = filtered.filter(function(p) { return matchProductQuery(p, q); });
      }

      // Hiển thị thanh thông báo kết quả tìm kiếm nếu có từ khóa
      const searchNotice = document.getElementById("storeSearchNotice");
      if (q) {
        if (searchNotice) {
          searchNotice.style.display = "block";
          searchNotice.innerHTML = '<div style="background: rgba(56, 189, 248, 0.08); border: 1px solid rgba(56, 189, 248, 0.25); border-radius: 8px; padding: 10px 16px; margin: 12px 0 16px 0; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px;">' +
            '<span style="font-size: 0.88rem; color: #e2e8f0;">' +
              '<i class="fa-solid fa-magnifying-glass" style="color:#38bdf8; margin-right:6px;"></i>' +
              'Kết quả tìm kiếm cho: <strong style="color:#38bdf8;">&quot;' + escapeHtml(q) + '&quot;</strong> (' + filtered.length + ' sản phẩm)' +
            '</span>' +
            '<button type="button" onclick="clearHeroSearch()" style="background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.3); color: #f87171; border-radius: 6px; padding: 5px 12px; font-size: 0.8rem; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 5px; transition: all 0.2s;">' +
              '<i class="fa-solid fa-xmark"></i> Xóa tìm kiếm' +
            '</button>' +
          '</div>';
        }
      } else {
        if (searchNotice) {
          searchNotice.style.display = "none";
          searchNotice.innerHTML = "";
        }
      }

      if (filtered.length === 0) {
        container.innerHTML = '<div style="grid-column: 1/-1; text-align:center; padding:50px 20px; color:#94a3b8;">' +
          '<i class="fa-solid fa-magnifying-glass" style="font-size:3rem; margin-bottom:14px; display:block; color:#475569;"></i>' +
          '<h4 style="font-size:1.05rem; color:#f1f5f9; margin-bottom:8px;">Không tìm thấy sản phẩm phù hợp</h4>' +
          '<p style="font-size:0.88rem; color:#64748b; max-width:460px; margin:0 auto 16px auto;">' +
            'Không tìm thấy sản phẩm nào khớp với từ khóa &quot;<strong>' + escapeHtml(q) + '</strong>&quot;' + (currentCategory && currentCategory !== "Tất cả" ? ' trong danh mục &quot;' + escapeHtml(currentCategory) + '&quot;' : '') + '.' +
          '</p>' +
          '<button type="button" onclick="clearHeroSearch()" style="background:#0284c7; color:#fff; border:none; padding:9px 20px; border-radius:6px; font-weight:700; cursor:pointer; font-size:0.85rem; box-shadow:0 4px 14px rgba(2,132,199,0.3);">' +
            '<i class="fa-solid fa-rotate-left" style="margin-right:6px;"></i> Xem lại tất cả sản phẩm' +
          '</button>' +
        '</div>';
        if (typeof renderPaginationUI === "function") {
          renderPaginationUI("storeProductPagination", 1, 0, "changeStoreProdPage");
        }
        return;
      }

      // Phân trang Sản Phẩm Nổi Bật:
      // Trên điện thoại (<= 768px): Hiển thị đúng 2 cột x 3 hàng = 6 sản phẩm mỗi trang, vừa khít không tràn màn hình
      // Trên máy tính (> 768px): Hiển thị đúng 6 cột x 2 hàng = 12 sản phẩm mỗi trang
      const isMobileGrid = (typeof window !== "undefined" && window.innerWidth <= 768);
      const STORE_PRODS_PER_PAGE = isMobileGrid ? 6 : 12;
      const page = (typeof paginationState !== "undefined" && paginationState.storeProd) ? paginationState.storeProd : 1;
      const totalPages = Math.ceil(filtered.length / STORE_PRODS_PER_PAGE);
      const safePage = Math.max(1, Math.min(page, totalPages));
      if (typeof paginationState !== "undefined") paginationState.storeProd = safePage;

      const startIndex = (safePage - 1) * STORE_PRODS_PER_PAGE;
      const pageProds = filtered.slice(startIndex, startIndex + STORE_PRODS_PER_PAGE);

      container.innerHTML = pageProds.map(p => renderSingleCard(p, false)).join("");

      // Cập nhật thông số trang ở thanh tiêu đề (< 1/1 >)
      const pageInfoEl = document.getElementById("storeProdHeaderPaginationInfo") || document.querySelector(".pagination-controls .pagination-info");
      if (pageInfoEl) pageInfoEl.innerText = safePage + "/" + (totalPages || 1);

      if (typeof renderPaginationUI === "function") {
        renderPaginationUI("storeProductPagination", safePage, filtered.length, "changeStoreProdPage", STORE_PRODS_PER_PAGE);
      }
    }


