    window.getSourceBalances = getSourceBalances;

    function getSourceBalance(provider = "sellmmo") {
      const balances = getSourceBalances();
      return (typeof balances[provider] === "number") ? balances[provider] : 999999;
    }
    window.getSourceBalance = getSourceBalance;

    // Khởi tạo bộ nhớ tạm số dư an toàn chống ReferenceError
    if (typeof window.cachedSourceBalances === "undefined" || !window.cachedSourceBalances) {
      window.cachedSourceBalances = {};
      try {
        var _storedB = localStorage.getItem("mmo_source_balances");
        if (_storedB) window.cachedSourceBalances = JSON.parse(_storedB) || {};
      } catch(e) {}
    }
    var cachedSourceBalances = window.cachedSourceBalances;
    var cachedSourceMoney = window.cachedSourceMoney || 0;

    async function fetchSingleSourceProfile(providerKey = "sellmmo", isManual = false) {
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[providerKey]) ? API_SOURCES[providerKey] : null;
      if (!pCfg) return;

      const moneyEl = document.getElementById("apiSourceMoneyDisplay_" + providerKey);
      if (moneyEl && isManual) {
        moneyEl.innerHTML = "<i class='fa-solid fa-spinner fa-spin' style='font-size:0.9rem;'></i>";
      }

      if (typeof window.cachedSourceBalances === "undefined" || !window.cachedSourceBalances) {
        window.cachedSourceBalances = {};
      }

      let moneyVal = (typeof window.cachedSourceBalances[providerKey] === "number") ? window.cachedSourceBalances[providerKey] : 0;
      let isSuccess = false;

      try {
        const res = await executeSourceApiCall("getProfile", { 
          provider: providerKey, 
          baseUrl: pCfg.baseUrl, 
          apiKey: pCfg.apiKey,
          username: pCfg.username,
          password: pCfg.password
        });

        if (res && res.success && res.data) {
          if (typeof res.data.money !== "undefined") {
            moneyVal = Math.round(Number(res.data.money) || 0);
            isSuccess = true;
          }
        }
      } catch(e) {
        console.warn("fetchSingleSourceProfile error for " + providerKey + ":", e);
      }

      window.cachedSourceBalances[providerKey] = moneyVal;
      cachedSourceBalances = window.cachedSourceBalances;
      try {
        localStorage.setItem("mmo_source_balances", JSON.stringify(window.cachedSourceBalances));
      } catch(e) {}

      if (moneyEl) {
        moneyEl.innerText = formatVND(moneyVal);
      }

      if (typeof renderSourceBalanceWarning === "function") {
        try { renderSourceBalanceWarning(); } catch(e) {}
      }

      if (isManual && typeof showToast === "function") {
        if (isSuccess) {
          showToast("Đã làm mới số dư ví " + pCfg.name + ": " + formatVND(moneyVal), "success");
        } else {
          showToast("Số dư ví " + pCfg.name + ": " + formatVND(moneyVal), "info");
        }
      }
    }
    window.fetchSingleSourceProfile = fetchSingleSourceProfile;

    async function fetchBothSourceBalances(isManual = false) {
      const provKeys = (typeof API_SOURCES !== "undefined") ? Object.keys(API_SOURCES) : ["mail72h", "sellmmo", "nguyenlieummo", "selltainguyenmmo", "shop1989nd", "ultrammo"];
      await Promise.allSettled(provKeys.map(k => fetchSingleSourceProfile(k, isManual)));
    }
    window.fetchBothSourceBalances = fetchBothSourceBalances;
    window.fetchApiSourceProfile = fetchBothSourceBalances;

    // Chỉ làm mới số dư nguồn khi tải trang và khi người dùng đang ở giao diện Quản Trị
    setTimeout(function() {
      if (typeof isAdminUser === "function" && isAdminUser()) {
        fetchBothSourceBalances(false);
      }
    }, 2000);
    setInterval(function() {
      if (typeof isAdminUser === "function" && isAdminUser() && !document.hidden) {
        const curView = typeof currentView !== "undefined" ? currentView : (localStorage.getItem("mmo_current_view") || "");
        if (curView === "viewAdmin") {
          fetchBothSourceBalances(false);
        }
      }
    }, 45000);

