      if (ogUrl) {
        previewBrandUrl(ogUrl, "setSiteOgImagePreview", "setSiteOgImageHint", "btnResetOgImage");
      }

      // Đồng bộ từ Turso Cloud Worker
      syncSettingsFromCloud();
