    // SẢN PHẨM 2 THANH BÊN THAY ĐỔI MỖI LẦN F5 & ĐỒNG BỘ TELEGRAM, MARQUEE
    // =========================================================================
    function renderDynamicFlankingProducts() {
      try {
        const activeProds = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products.filter(function(p) { return !p.isDeleted; }) : []);
        if (activeProds.length === 0) return;

        // Xáo trộn ngẫu nhiên danh sách sản phẩm mỗi lần chạy (F5)
        const shuffled = [...activeProds].sort(function() { return 0.5 - Math.random(); });
        const pLeft = shuffled[0] || activeProds[0];
        const pRight = shuffled[1] || (activeProds.length > 1 ? activeProds[1] : activeProds[0]);
        const pSidebar = shuffled[2] || (activeProds.length > 2 ? activeProds[2] : (activeProds.length > 1 ? activeProds[1] : activeProds[0]));

        function renderCardContent(cardEl, p) {
          if (!cardEl || !p) return;
          const rate = p.affiliateRate || 10;
          const commVnd = Math.round((p.price || 0) * (rate / 100));
          const commStr = (typeof formatVND === "function") ? formatVND(commVnd) : (commVnd.toLocaleString("vi-VN") + " Đ");
          const priceStr = (typeof formatVND === "function") ? formatVND(p.price || 0) : ((p.price || 0).toLocaleString("vi-VN") + " đ");
          const ratingStr = (p.rating || 5.0).toFixed ? (p.rating || 5.0).toFixed(1) : (p.rating || "5.0");

          cardEl.innerHTML = 
            '<div class="sponsor-img-wrap">' +
              '<img alt="' + escapeHtml(p.name) + '" src="' + escapeHtml((typeof resolveProductImage === "function") ? resolveProductImage(p) : (p.image || "https://iili.io/nFV4Rln.png")) + '" onerror="this.onerror=null; this.src=\'https://iili.io/nFV4Rln.png\';" />' +
            '</div>' +
            '<h4 class="sponsor-title">' +
              '<a href="?prod=' + encodeURIComponent(p.id) + '&amp;view=viewProductDetail" target="_blank" onclick="if(!event.ctrlKey &amp;&amp; !event.metaKey &amp;&amp; event.button === 0){ event.preventDefault(); event.stopPropagation(); openProductDetailById(\'' + escapeHtml(p.id) + '\'); }" style="color:inherit; text-decoration:none;">' +
                escapeHtml(p.name) +
              '</a>' +
            '</h4>' +
            '<span class="sponsor-commission"><i class="fa-solid fa-dollar-sign"></i> HOA HỒNG: ' + rate + '% (~' + commStr + ')</span>' +
            '<div class="sponsor-footer">' +
              '<span class="sponsor-price">' + priceStr + '</span>' +
              '<span class="sponsor-rating"><i class="fa-solid fa-star"></i> ' + ratingStr + '</span>' +
            '</div>';

          cardEl.onclick = function(e) {
            if (e.target.closest('a')) return;
            if (typeof openProductDetailById === "function") openProductDetailById(p.id);
          };
        }

        renderCardContent(document.getElementById("heroLeftSponsorCard"), pLeft);
        renderCardContent(document.getElementById("heroRightSponsorCard"), pRight);
        renderCardContent(document.getElementById("homeSidebarRightCard"), pSidebar);
      } catch(errFlank) {
        console.error("renderDynamicFlankingProducts error:", errFlank);
      }
    }
    window.renderDynamicFlankingProducts = renderDynamicFlankingProducts;

