    async function fetchCloudUsers(showNotification = false) {
      const apiUrl = getBackendApiUrl();
      if (!apiUrl) {
        if (showNotification) {
          showToast("Vui lòng dán Google Apps Script Web App URL vào Cài Đặt Hệ Thống & Google!", "warning");
        }
        return;
      }
      const adminEmail = (typeof currentUser !== "undefined" && currentUser && currentUser.email) ? currentUser.email : "khotaikhoanso.net@gmail.com";
      try {
        if (showNotification) showToast("Đang đồng bộ dữ liệu thành viên từ Google Sheet...", "info");
        const data = await callGasApi("adminGetUsers", { adminEmail: adminEmail });
        if (data && data.success && Array.isArray(data.users)) {
          let localUsers = getRegisteredUsers();
          data.users.forEach(cloudU => {
            const cEmail = (cloudU.email || "").toLowerCase().trim();
            if (!cEmail) return;
            const found = localUsers.find(u => (u.email || "").toLowerCase().trim() === cEmail);
            if (found) {
              found.name = cloudU.name || found.name;
              if (cloudU.balance !== undefined && cloudU.balance !== null && !isNaN(Number(cloudU.balance))) {
                found.balance = Number(cloudU.balance);
                if (currentUser && (currentUser.email || "").toLowerCase().trim() === cEmail) {
                  currentUser.balance = found.balance;
                  localStorage.setItem("mmo_user", JSON.stringify(currentUser));
                  updateUserUI();
                }
              }
              if (cloudU.role === "ADMIN" || cloudU.role === "Quản Trị Viên" || (typeof isAdminUser === "function" && isAdminUser({ email: cEmail }))) {
                found.role = "Quản Trị Viên";
              }
            } else {
              const isAdm = (typeof isAdminUser === "function" && isAdminUser({ email: cEmail })) || cloudU.role === "ADMIN" || cloudU.role === "Quản Trị Viên";
              localUsers.push({
                name: cloudU.name || cEmail.split("@")[0],
                email: cEmail,
                role: isAdm ? "Quản Trị Viên" : (cloudU.role || "Thành Viên"),
                balance: Number(cloudU.balance) || 0,
                created: cloudU.createdAt || new Date().toLocaleDateString("vi-VN"),
                avatar: cloudU.avatar || "https://cdn-icons-png.flaticon.com/512/3135/3135715.png"
              });
            }
          });
          saveRegisteredUsers(localUsers);
          if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
          if (typeof renderAdminDashboard === "function") renderAdminDashboard();
          if (showNotification) showToast("🎉 Đã đồng bộ thành công " + data.users.length + " thành viên từ Google Sheet!", "success");
        }
      } catch(err) {
        console.warn("fetchCloudUsers error:", err);
        if (showNotification) showToast("Lỗi đồng bộ Google Sheet. Vui lòng kiểm tra lại Web App URL!", "danger");
      }
    }
    window.fetchCloudUsers = fetchCloudUsers;

    // =========================================================================
    // 4. USER ORDERS & PROFILE ORDERS MANAGEMENT
    // =========================================================================
    function getOrderTimestamp(o) {
      if (!o) return 0;
      var rawNum = o.createdTimestamp || o.timestamp;
      if (typeof rawNum === "number" && rawNum > 0) {
        return (rawNum < 10000000000) ? rawNum * 1000 : rawNum;
      }
      if (typeof o.createdAt === "number" && o.createdAt > 0) {
        return (o.createdAt < 10000000000) ? o.createdAt * 1000 : o.createdAt;
      }

      var dateStr = String(o.createdAt || o.date || o.time || "").trim();
      if (dateStr) {
        if (/^[0-9]{10,13}$/.test(dateStr)) {
          var n = Number(dateStr);
          return (n < 10000000000) ? n * 1000 : n;
        }

        // Chuẩn hóa chuỗi ngày tháng: loại bỏ khoảng trắng đặc biệt (NNBSP), dấu phẩy
        var cleanStr = dateStr.replace(/[\u202f\u00a0]/g, " ").replace(/,/g, " ").replace(/\s+/g, " ").trim();

        // Định dạng 1: Giờ:Phút[:Giây] Ngày/Tháng/Năm (vd: "22:28 20/09/2026", "22:28:15 20/9/2026")
        var mTimeDate = cleanStr.match(/(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?\s+(\d{1,2})\/(\d{1,2})\/(\d{4})/);
        if (mTimeDate) {
          var h = parseInt(mTimeDate[1], 10) || 0;
          var min = parseInt(mTimeDate[2], 10) || 0;
          var sec = parseInt(mTimeDate[3], 10) || 0;
          var day = parseInt(mTimeDate[4], 10);
          var mon = parseInt(mTimeDate[5], 10) - 1;
          var yr = parseInt(mTimeDate[6], 10);
          var dObj = new Date(yr, mon, day, h, min, sec);
          if (!isNaN(dObj.getTime())) return dObj.getTime();
        }

        // Định dạng 2: Ngày/Tháng/Năm [Giờ:Phút[:Giây]] (vd: "20/09/2026 22:28", "12/9/2026 12:41:30", "11/9/2026")
        var mDateTime = cleanStr.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/);
        if (mDateTime) {
          var day2 = parseInt(mDateTime[1], 10);
          var mon2 = parseInt(mDateTime[2], 10) - 1;
          var yr2 = parseInt(mDateTime[3], 10);
          var h2 = mDateTime[4] ? parseInt(mDateTime[4], 10) : 0;
          var min2 = mDateTime[5] ? parseInt(mDateTime[5], 10) : 0;
          var sec2 = mDateTime[6] ? parseInt(mDateTime[6], 10) : 0;
          var dObj2 = new Date(yr2, mon2, day2, h2, min2, sec2);
          if (!isNaN(dObj2.getTime())) return dObj2.getTime();
        }

        // Định dạng 3: ISO 8601 YYYY-MM-DD[THH:mm:ss] (Từ Cloudflare Worker / Turso SQLite datetime('now') -> là giờ UTC!)
        var mIso = cleanStr.match(/(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/);
        if (mIso) {
          var yr3 = parseInt(mIso[1], 10);
          var mon3 = parseInt(mIso[2], 10) - 1;
          var day3 = parseInt(mIso[3], 10);
          var h3 = mIso[4] ? parseInt(mIso[4], 10) : 0;
          var min3 = mIso[5] ? parseInt(mIso[5], 10) : 0;
          var sec3 = mIso[6] ? parseInt(mIso[6], 10) : 0;
          // SQLite datetime('now') lưu theo UTC -> Date.UTC chuyển chuẩn xác sang UTC timestamp
          var dUtc = Date.UTC(yr3, mon3, day3, h3, min3, sec3);
          if (!isNaN(dUtc)) return dUtc;
        }

        // Fallback Date.parse chỉ khi không khớp định dạng ngày Việt Nam
        var parsed = Date.parse(cleanStr);
        if (!isNaN(parsed) && parsed > 0) return (parsed < 10000000000) ? parsed * 1000 : parsed;
      }

      var idStr = String(o.id || o.orderId || o.orderCode || "");
      var numMatch = idStr.match(/[0-9]{10,13}/);
      if (numMatch) {
        var t = Number(numMatch[0]);
        if (t < 10000000000) t *= 1000;
        if (t > 1500000000000) return t;
      }

      // Nếu đơn hàng vừa mua trong phiên này, ưu tiên timestamp hiện tại
      var cleanOid = idStr.replace("#", "").trim();
      if (cleanOid && (cleanOid === window.lastDeliveredOrderId || cleanOid === window.currentThankYouOrderId)) {
        return Date.now() + 100000000000;
      }

      return 0;
    }
    window.getOrderTimestamp = getOrderTimestamp;

    function formatOrderDate(rawDate, fallbackTs) {
      if (!rawDate) {
        if (fallbackTs && Number(fallbackTs) > 0) {
          return new Date(Number(fallbackTs)).toLocaleString("vi-VN");
        }
        return new Date().toLocaleString("vi-VN");
      }
      const s = String(rawDate).trim();
      if (/^\d{10,13}$/.test(s)) {
        return new Date(Number(s)).toLocaleString("vi-VN");
      }
      // NẾU rawDate LÀ DẠNG YYYY-MM-DD HH:mm:ss (từ SQLite / Worker), chuyển thành định dạng Việt Nam hiển thị chuẩn xác
      var mIso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[T\s](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?/);
      if (mIso) {
        var yr = parseInt(mIso[1], 10);
        var mon = parseInt(mIso[2], 10) - 1;
        var day = parseInt(mIso[3], 10);
        var h = parseInt(mIso[4], 10);
        var min = parseInt(mIso[5], 10);
        var sec = mIso[6] ? parseInt(mIso[6], 10) : 0;
        var d = new Date(Date.UTC(yr, mon, day, h, min, sec));
        return ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2) + ":" + ("0" + d.getSeconds()).slice(-2) + " " + ("0" + d.getDate()).slice(-2) + "/" + ("0" + (d.getMonth() + 1)).slice(-2) + "/" + d.getFullYear();
      }
      return s;
    }
    window.formatOrderDate = formatOrderDate;

    // =========================================================================
    // [BULLETPROOF ORDER SORTING ENGINE: NEWEST ORDERS ALWAYS ROW #1 AT TOP]
    // =========================================================================
    if (!window._recentOrderIds) window._recentOrderIds = [];

    function getBulletproofOrderTimestamp(item) {
      if (!item) return 0;
      const cId = String(item.orderId || item.id || item.orderCode || "").replace("#", "").trim();
      const lastId = String(window.lastDeliveredOrderId || window.currentThankYouOrderId || "").replace("#", "").trim();
      let storedLastId = "";
      try { storedLastId = String(localStorage.getItem("mmo_last_order_id") || "").replace("#", "").trim(); } catch(e) {}

      let recentList = Array.isArray(window._recentOrderIds) ? window._recentOrderIds : [];
      try {
        const sRecents = JSON.parse(sessionStorage.getItem("mmo_recent_order_ids") || "[]");
        if (Array.isArray(sRecents)) {
          recentList = Array.from(new Set(recentList.concat(sRecents)));
        }
      } catch(e) {}

      const recentIndex = recentList.indexOf(cId);
      const isDirectLast = (cId && (cId === lastId || cId === storedLastId));

      let ts = 0;
      if (typeof getOrderTimestamp === "function") {
        ts = getOrderTimestamp(item);
      }
      if (!ts || isNaN(ts) || ts <= 0) {
        ts = Number(item.createdTimestamp || item.createdAt || item.timestamp || 0);
      }
      if (!ts || isNaN(ts) || ts <= 0) {
        if (typeof getOrderTimestamp === "function") {
          ts = getOrderTimestamp({ date: item.date || item.createdAt || item.time });
        }
      }
      if (!ts || isNaN(ts) || ts <= 0) {
        ts = Date.parse(item.date || item.createdAt || "") || 0;
      }

      // Đơn vừa mua trong phiên: Ưu tiên tuyệt đối lên dòng đầu tiên (#1)
      if (isDirectLast) {
        return (ts > 0 ? ts : Date.now()) + 100000000000;
      } else if (recentIndex !== -1) {
        return (ts > 0 ? ts : Date.now()) + 50000000000 - (recentIndex * 1000000);
      }

      return (typeof ts === "number" && !isNaN(ts)) ? ts : 0;
    }
    window.getBulletproofOrderTimestamp = getBulletproofOrderTimestamp;

    function sortOrdersNewestFirst(orders) {
      if (!Array.isArray(orders)) return [];
      return orders.sort(function(a, b) {
        return getBulletproofOrderTimestamp(b) - getBulletproofOrderTimestamp(a);
      });
    }
    window.sortOrdersNewestFirst = sortOrdersNewestFirst;

    
    // =========================================================================
    // [BULLETPROOF ORDER PERSISTENCE & REALTIME ENGINE]
    // Lưu trữ đơn hàng đa tầng (In-Memory, SessionStorage, LocalStorage, Cloud, Realtime Broadcast)
    // =========================================================================
    if (!window._mmoInMemoryOrders) window._mmoInMemoryOrders = [];

    function safeStorageSet(key, list, maxItems = 250) {
      if (!Array.isArray(list)) return;
      try {
        let cleanList = list.slice(0, maxItems);
        localStorage.setItem(key, JSON.stringify(cleanList));
      } catch(quotaErr) {
        // Tự động dọn dẹp cache phụ để giải phóng dung lượng cho đơn hàng cốt lõi
        try {
          localStorage.removeItem('mmo_cached_source_products');
          localStorage.removeItem('mmo_cache_api_products');
          let cleanList = list.slice(0, Math.min(100, maxItems));
          localStorage.setItem(key, JSON.stringify(cleanList));
        } catch(e2) {
          console.warn('SafeStorage quota write fallback for ' + key + ':', e2);
        }
      }
    }
    window.safeStorageSet = safeStorageSet;

    function recordAndSaveNewOrder(orderObj) {
      if (!orderObj) return null;

      const orderId = String(orderObj.orderId || orderObj.id || orderObj.orderCode || ('MMO' + Math.floor(100000 + Math.random() * 900000))).replace('#', '').trim();
      const nowTs = Number(orderObj.createdTimestamp || orderObj.createdAt || Date.now());
      const formattedDate = (typeof formatOrderDate === 'function') ? formatOrderDate(orderObj.date, nowTs) : (orderObj.date || new Date().toLocaleString('vi-VN'));

      const cleanObj = Object.assign({}, orderObj, {
        id: orderId,
        orderId: orderId,
        orderCode: orderId,
        createdTimestamp: nowTs,
        createdAt: nowTs,
        date: formattedDate,
        status: orderObj.status || 'COMPLETED',
        statusText: orderObj.statusText || 'Hoàn thành',
        type: orderObj.type || 'REGULAR'
      });

      // 1. Lưu vào In-Memory Array (Đảm bảo 100% không bao giờ mất trong phiên này)
      if (!window._mmoInMemoryOrders) window._mmoInMemoryOrders = [];
      window._mmoInMemoryOrders = window._mmoInMemoryOrders.filter(o => (o && o.id !== orderId && o.orderId !== orderId));
      window._mmoInMemoryOrders.unshift(cleanObj);

      // Cập nhật Last Delivered ID & Danh sách đơn vừa mua trong phiên (Newest-First)
      window.lastDeliveredOrderId = orderId;
      window.lastDeliveredCredentials = cleanObj.credentials || '';
      window.currentThankYouOrderId = orderId;
      if (!window._recentOrderIds) window._recentOrderIds = [];
      if (!window._recentOrderIds.includes(orderId)) window._recentOrderIds.unshift(orderId);
      try {
        let recents = JSON.parse(sessionStorage.getItem('mmo_recent_order_ids') || '[]');
        if (!recents.includes(orderId)) recents.unshift(orderId);
        sessionStorage.setItem('mmo_recent_order_ids', JSON.stringify(recents.slice(0, 50)));
      } catch(e) {}

      // 2. Lưu vào SessionStorage
      try {
        let sess = JSON.parse(sessionStorage.getItem('mmo_session_orders') || '[]');
        sess = sess.filter(o => (o && o.id !== orderId && o.orderId !== orderId));
        sess.unshift(cleanObj);
        sessionStorage.setItem('mmo_session_orders', JSON.stringify(sess.slice(0, 100)));
      } catch(e) {}

      // 3. Lưu vào LocalStorage đa tầng
      ['mmo_orders', 'mmo_user_orders', 'mmo_all_orders'].forEach(function(k) {
        try {
          let list = JSON.parse(localStorage.getItem(k) || '[]');
          list = list.filter(o => (o && o.id !== orderId && o.orderId !== orderId));
          list.unshift(cleanObj);
          safeStorageSet(k, list, 250);
        } catch(e) {}
      });

      try {
        localStorage.setItem('mmo_last_order_id', orderId);
        if (cleanObj.credentials) localStorage.setItem('mmo_last_credentials', cleanObj.credentials);
      } catch(e) {}

      // 4. Ghi nhận giao dịch ví & biến động số dư
      try {
        const totalAmt = Number(cleanObj.total || cleanObj.totalPrice || 0);
        const curUser = (typeof currentUser !== 'undefined' && currentUser) ? currentUser : null;
        const cleanMail = (cleanObj.userEmail || (curUser && curUser.email) || '').toLowerCase().trim();
        const userName = (curUser ? (curUser.username || curUser.name || cleanMail) : cleanMail) || 'Khách Hàng';
        const newBal = (curUser && curUser.balance !== undefined) ? Number(curUser.balance) : null;
        const purchaseNote = 'Mua SP: ' + (cleanObj.productName || 'Sản phẩm') + ((cleanObj.variant && cleanObj.variant !== 'Mặc định') ? (' (' + cleanObj.variant + ')') : '') + ' - Đơn #' + orderId;

        if (typeof recordTransaction === 'function') {
          recordTransaction(cleanMail, userName, 'Thanh toán mua hàng', -totalAmt, newBal, purchaseNote);
        }

        const txObj = {
          id: 'ORD_' + orderId + '_' + Date.now(),
          txId: 'ORD_' + orderId,
          orderId: orderId,
          userEmail: cleanMail,
          userName: userName,
          type: 'Thanh toán mua hàng',
          amount: -totalAmt,
          balanceAfter: newBal,
          note: purchaseNote,
          time: formattedDate,
          date: formattedDate
        };

        let txs = JSON.parse(localStorage.getItem('mmo_transactions') || '[]');
        txs = txs.filter(t => t && t.orderId !== orderId);
        txs.unshift(txObj);
        safeStorageSet('mmo_transactions', txs, 200);
        safeStorageSet('mmo_wallet_transactions', txs, 200);

        let bLogs = JSON.parse(localStorage.getItem('mmo_balance_logs') || '[]');
        bLogs = bLogs.filter(b => b && b.orderId !== orderId);
        bLogs.unshift({
          id: 'TX_ORD_' + Date.now(),
          orderId: orderId,
          userEmail: cleanMail,
          type: 'Thanh toán mua hàng',
          amount: -totalAmt,
          balanceAfter: newBal,
          note: purchaseNote,
          time: formattedDate,
          date: formattedDate
        });
        safeStorageSet('mmo_balance_logs', bLogs, 200);
      } catch(e) {}

      // 5. Ghi nhận hoa hồng Affiliate nếu có
      if (typeof recordAffiliateCommissionForOrder === 'function') {
        try { recordAffiliateCommissionForOrder(cleanObj); } catch(e) {}
      }

      // 6. Đồng bộ lên Turso Cloud và Worker Cloud API
      try {
        if (typeof TURSO_CLIENT !== 'undefined' && TURSO_CLIENT.isConfigured() && typeof TURSO_CLIENT.recordOrder === 'function') {
          TURSO_CLIENT.recordOrder(cleanObj).catch(e => console.warn('Turso recordOrder error:', e));
        }
      } catch(e) {}

      try {
        if (typeof MMO_WORKER_API !== 'undefined' && typeof MMO_WORKER_API.getApiUrl === 'function') {
          fetch(MMO_WORKER_API.getApiUrl() + '/api/orders/sync', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ order: cleanObj, orders: [cleanObj] }),
            keepalive: true
          }).catch(() => {});
        }
      } catch(e) {}

      // 7. Phát sóng Realtime đa Tab qua BroadcastChannel 0ms
      try {
        if (typeof BroadcastChannel !== 'undefined') {
          const bcGlobal = new BroadcastChannel('mmo_channel');
          bcGlobal.postMessage({ type: 'NEW_ORDER', order: cleanObj, timestamp: Date.now() });

          const bcOrders = new BroadcastChannel('mmo_orders_channel');
          bcOrders.postMessage({ type: 'NEW_ORDER', order: cleanObj, timestamp: Date.now() });
        }
      } catch(e) {}

      // 8. Đánh dấu viewDirty và ngay lập tức Re-render tất cả bảng dữ liệu liên quan
      try {
        if (typeof _viewDirty !== 'undefined') {
          _viewDirty['viewProfile'] = true;
          _viewDirty['viewAdmin'] = true;
        }
        if (typeof renderProfileOrders === 'function') renderProfileOrders();
        if (typeof renderAdminOrdersTable === 'function') renderAdminOrdersTable();
        if (typeof updateAdminSidebarBadges === 'function') updateAdminSidebarBadges();
        if (typeof renderSystemOverview === 'function') renderSystemOverview();
        if (typeof renderUserWalletTransactions === 'function') renderUserWalletTransactions();
        if (typeof renderUserBalanceLogs === 'function') renderUserBalanceLogs();
      } catch(e) {}

      return cleanObj;
    }
    window.recordAndSaveNewOrder = recordAndSaveNewOrder;

