    function renderArticleRelatedGrid(currentBlog) {
      const container = document.getElementById("articleRelatedGrid");
      if (!container) return;
      const blogs = (MOCK_DATA && MOCK_DATA.blogs) ? MOCK_DATA.blogs : [];
      let related = blogs.filter(b => b.id !== currentBlog.id && b.category === currentBlog.category);
      if (related.length < 4) {
        const others = blogs.filter(b => b.id !== currentBlog.id && !related.some(r => r.id === b.id));
        related = related.concat(others);
      }
      // Trên điện thoại (<= 768px): hiển thị đúng 3 bài viết đề xuất đầy đủ thông tin mô tả
      // Trên máy tính: hiển thị 4 bài viết lấp đầy khoảng trống ngang
      const isMobile = window.innerWidth <= 768;
      const targetCount = isMobile ? 3 : 4;
      const items = related.slice(0, targetCount);

      container.innerHTML = items.map(function(b) {
        const rViews = getBlogRandomViews(b);
        // Nâng cấp ảnh thumbnail lên độ phân giải sắc nét Full HD
        let cImg = upgradeBloggerImageToFullHd(String(b.image || ''));
        return '<div class="blog-card-full" onclick="openBlogDetail(\'' + b.id + '\')">' +
          '<div class="blog-card-img">' +
            '<img src="' + cImg + '" alt="' + escapeHtml(b.title) + '" loading="lazy"/>' +
          '</div>' +
          '<div class="blog-card-body">' +
            '<span class="blog-badge-cat">' + escapeHtml(b.category) + '</span>' +
            '<h3 class="blog-card-heading">' + escapeHtml(b.title) + '</h3>' +
            '<p class="blog-card-snippet">' + escapeHtml(b.snippet || b.title) + '</p>' +
            '<div class="blog-card-footer">' +
              '<span><i class="fa-regular fa-clock"></i> ' + b.date + '</span>' +
              '<span><i class="fa-regular fa-eye"></i> ' + rViews + '</span>' +
            '</div>' +
          '</div>' +
        '</div>';
      }).join("");
    }
