    async function checkSingleFbUser(uid) {
      if (!uid || uid.length < 2) return false;

      if (/\b(die|banned|checkpoint|disabled|suspended|khoa)\b/i.test(uid)) {
        return false;
      }

      if (/^\d+$/.test(uid)) {
        return new Promise((resolve) => {
          let isDone = false;
          const img = new Image();
          const timer = setTimeout(() => {
            if (!isDone) {
              isDone = true;
              resolve(true);
            }
          }, 3500);

          img.onload = function() {
            if (!isDone) {
              isDone = true;
              clearTimeout(timer);
              resolve(img.naturalWidth > 1);
            }
          };

          img.onerror = function() {
            if (!isDone) {
              isDone = true;
              clearTimeout(timer);
              resolve(false);
            }
          };

          img.src = "https://graph.facebook.com/" + encodeURIComponent(uid) + "/picture?type=normal&t=" + Date.now();
        });
      }

      return new Promise((resolve) => {
        let isDone = false;
        const img = new Image();
        const timer = setTimeout(() => {
          if (!isDone) {
            isDone = true;
            resolve(true);
          }
        }, 3000);

        img.onload = function() {
          if (!isDone) {
            isDone = true;
            clearTimeout(timer);
            resolve(true);
          }
        };
        img.onerror = function() {
          if (!isDone) {
            isDone = true;
            clearTimeout(timer);
            resolve(true);
          }
        };
        img.src = "https://graph.facebook.com/" + encodeURIComponent(uid) + "/picture?type=normal&t=" + Date.now();
      });
    }

