    // ==========================================
    // TOOL 3: LẤY MÃ 2FA (TOTP ENGINE)
    // ==========================================
    function dec2hex(s) {
      return (s < 15.5 ? "0" : "") + Math.round(s).toString(16);
    }
    function hex2dec(s) {
      return parseInt(s, 16);
    }
    function base32tohex(base32) {
      const base32chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
      let bits = "";
      let hex = "";
      let clean = base32.toUpperCase().replace(/\s+/g, "").replace(/=+$/, "");
      for (let i = 0; i < clean.length; i++) {
        const val = base32chars.indexOf(clean.charAt(i));
        if (val === -1) continue;
        bits += val.toString(2).padStart(5, '0');
      }
      for (let i = 0; i + 4 <= bits.length; i += 4) {
        const chunk = bits.substr(i, 4);
        hex = hex + parseInt(chunk, 2).toString(16);
      }
      return hex;
    }

    function leftpad(str, len, pad) {
      if (len + 1 >= str.length) {
        str = Array(len + 1 - str.length).join(pad) + str;
      }
      return str;
    }

    function getTotpToken(secret) {
      return (typeof generateTOTP === "function") ? generateTOTP(secret) : "ERROR";
    }

