    function renderSitemapView() {
      const container = document.getElementById("sitemapProductList");
      if (!container) return;
      const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
      container.innerHTML = prods.map(p => {
        return '<div style="border-bottom:1px solid #1e293b; padding-bottom:8px;">' +
          '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" style="color:#e2e8f0; text-decoration:none; font-size:0.85rem; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
            '<span style="font-weight:600;"><i class="fa-solid fa-box" style="color:#10b981; font-size:0.75rem; margin-right:6px;"></i>' + escapeHtml(p.name) + '</span>' +
            '<span style="color:#38bdf8; font-weight:700; white-space:nowrap;">' + formatVND(p.price || 0) + '</span>' +
          '</a>' +
        '</div>';
      }).join("");
    }
    window.renderSitemapView = renderSitemapView;

    // [SEO GOOGLE INDEX]: Tự động khai báo danh mục tất cả sản phẩm dưới dạng Schema ItemList cho Googlebot
function getProductSchemaReviews(p, idx) {
      let customRevs = [];
      try {
        const stored = localStorage.getItem("mmo_product_reviews_" + (p ? p.id : ""));
        if (stored) {
          const parsed = JSON.parse(stored);
          if (Array.isArray(parsed) && parsed.length > 0) customRevs = parsed;
        }
      } catch(e) {}

      const pSold = (p && typeof p.soldCount === "number") ? p.soldCount : 86;
      const ratingCount = Math.max(38, pSold + (((idx || 0) * 7) % 45) + 25);
      const ratingVal = (4.8 + (((idx || 0) * 3) % 3) * 0.1).toFixed(1); // 4.8, 4.9, hoặc 5.0
      const prodName = (p && p.name) ? p.name : "Tài khoản MMO";

      let reviewsList = [];
      if (customRevs.length > 0) {
        reviewsList = customRevs.slice(0, 3).map((r, rIdx) => ({
          "@type": "Review",
          "reviewRating": {
            "@type": "Rating",
            "ratingValue": String(r.rating || 5),
            "bestRating": "5",
            "worstRating": "1"
          },
          "author": {
            "@type": "Person",
            "name": (r.name && !r.name.includes("@")) ? r.name : (r.name ? r.name.split("@")[0] + " (Khách mua)" : "Khách Hàng Xác Thực")
          },
          "datePublished": "2026-09-" + (20 + (rIdx % 8)),
          "reviewBody": r.comment || "Tài khoản chất lượng cao, đúng mô tả, giao hàng tự động siêu tốc."
        }));
      } else {
        reviewsList = [
          {
            "@type": "Review",
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": "5",
              "bestRating": "5",
              "worstRating": "1"
            },
            "author": {
              "@type": "Person",
              "name": "Hoàng Nam (Đã Mua Hàng)"
            },
            "datePublished": "2026-09-25",
            "reviewBody": "Tài khoản " + prodName + " chất lượng rất tốt, đúng mô tả, đăng nhập mượt mà không checkpoint. Ủng hộ shop lâu dài!"
          },
          {
            "@type": "Review",
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": "5",
              "bestRating": "5",
              "worstRating": "1"
            },
            "author": {
              "@type": "Person",
              "name": "Duy Marketing (MMO Pro)"
            },
            "datePublished": "2026-09-22",
            "reviewBody": "Giao hàng tự động trong 5 giây, tài khoản live chuẩn, support nhiệt tình và uy tín số 1."
          },
          {
            "@type": "Review",
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": "5",
              "bestRating": "5",
              "worstRating": "1"
            },
            "author": {
              "@type": "Person",
              "name": "Văn Huy Agency"
            },
            "datePublished": "2026-09-20",
            "reviewBody": "Đã mua nhiều lần bên shop, tài khoản form rất cứng, chế độ bảo hành 1-đổi-1 nhanh chóng nên rất yên tâm."
          }
        ];
      }

      return {
        aggregateRating: {
          "@type": "AggregateRating",
          "ratingValue": String(ratingVal),
          "reviewCount": ratingCount,
          "ratingCount": ratingCount,
          "bestRating": "5",
          "worstRating": "1"
        },
        review: reviewsList
      };
    }
    window.getProductSchemaReviews = getProductSchemaReviews;

    function injectAllProductsSchema() {
      try {
        const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        if (prods.length === 0) return;
        const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        const visibleProds = prods.filter(p => p && p.id && !deletedIds.includes(p.id));
        if (visibleProds.length === 0) return;

        const baseUrl = window.location.origin + window.location.pathname;
        const siteUrl = "https://cuahangcuaban.com/";

        const prodShippingDetails = {
          "@type": "OfferShippingDetails",
          "shippingRate": { "@type": "MonetaryAmount", "value": "0", "currency": "VND" },
          "shippingDestination": { "@type": "DefinedRegion", "addressCountry": "VN" },
          "deliveryTime": {
            "@type": "ShippingDeliveryTime",
            "handlingTime": { "@type": "QuantitativeValue", "minValue": 0, "maxValue": 0, "unitCode": "DAY" },
            "transitTime": { "@type": "QuantitativeValue", "minValue": 0, "maxValue": 0, "unitCode": "DAY" }
          }
        };
        const prodReturnPolicy = {
          "@type": "MerchantReturnPolicy",
          "applicableCountry": "VN",
          "returnPolicyCategory": "https://schema.org/MerchantReturnFiniteReturnWindow",
          "merchantReturnDays": 1,
          "returnMethod": "https://schema.org/ReturnByMail",
          "returnFees": "https://schema.org/FreeReturn"
        };

        // Kiểm tra xem có đang ở trang chi tiết sản phẩm cụ thể hay không
        const urlParams = new URLSearchParams(window.location.search);
        const targetProdId = urlParams.get("prod") || urlParams.get("product") || (window.location.hash && window.location.hash.startsWith("#product_") ? window.location.hash.replace("#product_", "") : null);

        if (targetProdId) {
          // Xóa schema danh sách cũ nếu có
          const s = document.getElementById("schemaAllProductsItemList");
          if (s) s.remove();

          // Tìm sản phẩm cụ thể để tạo Schema Product độc lập hoàn hảo 100%
          const curP = visibleProds.find(item => item && (String(item.id) === String(targetProdId) || String(item.id).toLowerCase() === String(targetProdId).toLowerCase())) || visibleProds[0];
          if (curP) {
            let detailScriptEl = document.getElementById("schemaSingleProductDetail");
            if (!detailScriptEl) {
              detailScriptEl = document.createElement("script");
              detailScriptEl.id = "schemaSingleProductDetail";
              detailScriptEl.type = "application/ld+json";
              document.head.appendChild(detailScriptEl);
            }
            const prodUrl = baseUrl + "/search?q=" + encodeURIComponent(curP.id);
            const price = (curP.variants && curP.variants[0] && curP.variants[0].price) ? curP.variants[0].price : (curP.price || 0);
            const imgUrl = (typeof resolveProductSeoSchemaImage === "function") ? resolveProductSeoSchemaImage(curP) : ((curP.image && !curP.image.startsWith("data:")) ? curP.image : "https://iili.io/nFV4Rln.png");
            const ratingData = getProductSchemaReviews(curP, 0);

            const singleProdSchema = {
              "@context": "https://schema.org",
              "@type": "Product",
              "@id": prodUrl + "#product",
              "name": curP.name,
              "description": (curP.description || ("Mua " + curP.name + " tự động 24/7 uy tín, giá rẻ nhất Việt Nam.")).slice(0, 300),
              "url": prodUrl,
              "image": [imgUrl],
              "sku": curP.id,
              "mpn": curP.id,
              "identifier_exists": "false",
              "brand": { "@type": "Brand", "name": "KHO TÀI KHOẢN SỐ" },
              "category": curP.category || "Tài Khoản MMO",
              "offers": {
                "@type": "Offer",
                "url": prodUrl,
                "priceCurrency": "VND",
                "price": price,
                "priceValidUntil": "2027-12-31",
                "validFrom": "2026-01-01",
                "availability": (curP.stock > 0) ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
                "itemCondition": "https://schema.org/NewCondition",
                "seller": { "@type": "Organization", "name": "KHO TÀI KHOẢN SỐ" },
                "shippingDetails": prodShippingDetails,
                "hasMerchantReturnPolicy": prodReturnPolicy
              },
              "aggregateRating": ratingData.aggregateRating,
              "review": ratingData.review
            };
            detailScriptEl.textContent = JSON.stringify(singleProdSchema);
            return;
          }
        }

        // Nếu ở trang chủ / danh mục: Tạo ItemList chứa toàn bộ sản phẩm kèm AggregateRating & Review
        let listDetailEl = document.getElementById("schemaSingleProductDetail");
        if (listDetailEl) listDetailEl.remove();

        let scriptEl = document.getElementById("schemaAllProductsItemList");
        if (!scriptEl) {
          scriptEl = document.createElement("script");
          scriptEl.id = "schemaAllProductsItemList";
          scriptEl.type = "application/ld+json";
          document.head.appendChild(scriptEl);
        }

        const graphSchema = {
          "@context": "https://schema.org",
          "@graph": [
            {
              "@type": "WebSite",
              "@id": siteUrl + "#website",
              "url": siteUrl,
              "name": "KHO TÀI KHOẢN SỐ",
              "description": "He thong mua ban tai khoan mang xa hoi, cong cu MMO, proxy tu dong 24/7 uy tin so 1 Viet Nam",
              "publisher": { "@id": siteUrl + "#organization" }
            },
            {
              "@type": "Organization",
              "@id": siteUrl + "#organization",
              "name": "KHO TÀI KHOẢN SỐ",
              "url": siteUrl,
              "logo": { "@type": "ImageObject", "url": "https://iili.io/nFV4Rln.png" }
            },
            {
              "@type": "ItemList",
              "@id": siteUrl + "#productlist",
              "name": "Danh Sach San Pham Tai Khoan MMO - khotaikhoanso.net",
              "numberOfItems": visibleProds.length,
              "itemListElement": visibleProds.map((p, idx) => {
                const prodUrl = baseUrl + "/search?q=" + encodeURIComponent(p.id);
                const price = (p.variants && p.variants[0] && p.variants[0].price) ? p.variants[0].price : (p.price || 0);
                const imgUrl = (typeof resolveProductSeoSchemaImage === "function") ? resolveProductSeoSchemaImage(p) : ((p.image && !p.image.startsWith("data:")) ? p.image : "https://iili.io/nFV4Rln.png");
                const ratingData = getProductSchemaReviews(p, idx);
                return {
                  "@type": "ListItem",
                  "position": idx + 1,
                  "item": {
                    "@type": "Product",
                    "@id": prodUrl + "#product",
                    "name": p.name,
                    "description": (p.description || ("Mua " + p.name + " tu dong 24/7 uy tin, gia re nhat Viet Nam.")).slice(0, 300),
                    "url": prodUrl,
                    "image": [imgUrl],
                    "sku": p.id,
                    "mpn": p.id,
                    "identifier_exists": "false",
                    "brand": { "@type": "Brand", "name": "KHO TÀI KHOẢN SỐ" },
                    "category": p.category || "Tai Khoan MMO",
                    "offers": {
                      "@type": "Offer",
                      "url": prodUrl,
                      "priceCurrency": "VND",
                      "price": price,
                      "priceValidUntil": "2027-12-31",
                      "validFrom": "2026-01-01",
                      "availability": (p.stock > 0) ? "https://schema.org/InStock" : "https://schema.org/OutOfStock",
                      "itemCondition": "https://schema.org/NewCondition",
                      "seller": { "@type": "Organization", "name": "KHO TÀI KHOẢN SỐ" },
                      "shippingDetails": prodShippingDetails,
                      "hasMerchantReturnPolicy": prodReturnPolicy
                    },
                    "aggregateRating": ratingData.aggregateRating,
                    "review": ratingData.review
                  }
                };
              })
            }
          ]
        };
        scriptEl.textContent = JSON.stringify(graphSchema);
      } catch(e) { console.warn("injectAllProductsSchema error:", e); }
    }
    window.injectAllProductsSchema = injectAllProductsSchema;

    // SEO CHUM: Render related products widget
    function renderRelatedProductsSeo(currentProduct) {
      try {
        const container = document.getElementById("dtlSeoRelatedProducts");
        if (!container) return;
        const prods = (MOCK_DATA && Array.isArray(MOCK_DATA.products)) ? MOCK_DATA.products : [];
        const deletedIds = (typeof getDeletedProductIds === "function") ? getDeletedProductIds() : [];
        const related = prods.filter(p =>
          p && p.id && p.id !== currentProduct.id &&
          !deletedIds.includes(p.id) &&
          p.category === currentProduct.category
        ).slice(0, 6);

        if (related.length === 0) { container.style.display = "none"; return; }
        container.style.display = "block";
        const baseUrl = window.location.origin + window.location.pathname;
        const relItems = related.map(rp => {
          const rpUrl = baseUrl + "?prod=" + encodeURIComponent(rp.id) + "&view=viewProductDetail";
          const rpPrice = (rp.variants && rp.variants[0] && rp.variants[0].price) ? rp.variants[0].price : (rp.price || 0);
          const rpStock = (typeof getProductStockCount === "function") ? getProductStockCount(rp) : (rp.stock || 0);
          const rpPriceStr = (typeof formatVND === "function") ? formatVND(rpPrice) : rpPrice.toLocaleString("vi-VN") + "d";
          const eName = (typeof escapeHtml === "function") ? escapeHtml(rp.name) : rp.name.replace(/</g,"&lt;").replace(/>/g,"&gt;");
          return '<a href="' + rpUrl + '" onclick="event.preventDefault(); openProductDetailById(\'' + rp.id + '\')" '
            + 'style="display:block; background:#0d121f; border:1px solid #1e293b; border-radius:8px; padding:8px; text-decoration:none;" '
            + 'rel="noopener" title="' + eName + '">'
            + '<img src="' + (rp.image || "https://iili.io/nFV4Rln.png") + '" alt="' + eName + '" '
            + 'style="width:100%; height:70px; object-fit:cover; border-radius:5px; margin-bottom:6px;" loading="lazy"/>'
            + '<div style="font-size:0.72rem; color:#cbd5e1; line-height:1.3; margin-bottom:4px;">' + eName + '</div>'
            + '<div style="font-size:0.75rem; color:#10b981; font-weight:700;">' + rpPriceStr + '</div>'
            + '<div style="font-size:0.65rem; color:' + (rpStock > 0 ? '#10b981' : '#ef4444') + ';">' + (rpStock > 0 ? 'Con hang' : 'Het hang') + '</div>'
            + '</a>';
        }).join("");
        container.innerHTML = '<div style="margin-top:20px; border-top:1px solid #1e293b; padding-top:16px;">'
          + '<h3 style="font-size:0.92rem; color:#38bdf8; margin-bottom:12px; display:flex; align-items:center; gap:6px;">'
          + '<i class="fa-solid fa-layer-group"></i> San Pham Lien Quan</h3>'
          + '<div style="display:grid; grid-template-columns:repeat(auto-fill,minmax(140px,1fr)); gap:8px;">'
          + relItems + '</div></div>';
      } catch(e) {}
    }
    window.renderRelatedProductsSeo = renderRelatedProductsSeo;



    window.formatVND = formatVND;

    window.toggleLockUser = toggleLockUser;

    window.handleRemoveAdminEmail = handleRemoveAdminEmail;

    window.handleAddAdminEmail = handleAddAdminEmail;

    window.renderAdminEmailsList = renderAdminEmailsList;


    // ==================== ALL PRODUCTS PAGE LOGIC ====================
    let allProdCurrentCat = "Tất cả";
    let allProdCurrentSort = "featured";
    let allProdViewMode = "grid";
    let allProdCurrentPage = 1;
    const ALL_PROD_PAGE_SIZE = 21; // 7 cột x 3 hàng = 21 sản phẩm/trang

    function setAllProdCategory(cat) {
      allProdCurrentCat = cat;
      allProdCurrentPage = 1;
      renderAllProductsPage();
    }
    window.setAllProdCategory = setAllProdCategory;

    function setAllProdSort(sortType) {
      allProdCurrentSort = sortType;
      allProdCurrentPage = 1;
      
      const sortBtns = ["sortBtnFeatured", "sortBtnBestseller", "sortBtnPriceAsc", "sortBtnPriceDesc", "sortBtnNewest"];
      sortBtns.forEach(function(bId) {
        const btn = document.getElementById(bId);
        if (btn) {
          btn.style.background = "#070a12";
          btn.style.color = "#94a3b8";
          btn.style.borderColor = "#1e293b";
        }
      });
      const activeBtnMap = {
        featured: "sortBtnFeatured",
        bestseller: "sortBtnBestseller",
        price_asc: "sortBtnPriceAsc",
        price_desc: "sortBtnPriceDesc",
        newest: "sortBtnNewest"
      };
      const activeBtn = document.getElementById(activeBtnMap[sortType]);
      if (activeBtn) {
        activeBtn.style.background = "#ef4444";
        activeBtn.style.color = "#fff";
        activeBtn.style.borderColor = "#ef4444";
      }

      renderAllProductsPage();
    }
    window.setAllProdSort = setAllProdSort;

    function setAllProdViewMode(mode) {
      allProdViewMode = mode;
      const gridBtn = document.getElementById("viewModeGridBtn");
      const listBtn = document.getElementById("viewModeListBtn");
      if (gridBtn && listBtn) {
        if (mode === "grid") {
          gridBtn.style.background = "rgba(239,68,68,0.15)";
          gridBtn.style.borderColor = "#ef4444";
          gridBtn.style.color = "#ef4444";
          listBtn.style.background = "#070a12";
          listBtn.style.borderColor = "#1e293b";
          listBtn.style.color = "#94a3b8";
        } else {
          listBtn.style.background = "rgba(239,68,68,0.15)";
          listBtn.style.borderColor = "#ef4444";
          listBtn.style.color = "#ef4444";
          gridBtn.style.background = "#070a12";
          gridBtn.style.borderColor = "#1e293b";
          gridBtn.style.color = "#94a3b8";
        }
      }
      renderAllProductsPage();
    }
    window.setAllProdViewMode = setAllProdViewMode;

    function handleAllProdFilter() {
      allProdCurrentPage = 1;
      renderAllProductsPage();
    }
    window.handleAllProdFilter = handleAllProdFilter;

    function resetAllProdFilter() {
      const sInp = document.getElementById("allProdSearchInp");
      if (sInp) sInp.value = "";
      const minInp = document.getElementById("allProdPriceMin");
      if (minInp) minInp.value = "";
      const maxInp = document.getElementById("allProdPriceMax");
      if (maxInp) maxInp.value = "";
      const inStock = document.getElementById("allProdInStockOnly");
      if (inStock) inStock.checked = false;
      const curr = document.getElementById("allProdCurrencySelect");
      if (curr) curr.value = "ALL";
      allProdCurrentCat = "Tất cả";
      allProdCurrentSort = "featured";
      allProdCurrentPage = 1;
      setAllProdSort("featured");
    }
    window.resetAllProdFilter = resetAllProdFilter;

    function toggleMobileFilter() {
      var sidebar = document.getElementById("allProdSidebar");
      var btn = document.getElementById("mobileFilterToggleBtn");
      var btnText = document.getElementById("mobileFilterBtnText");
      if (!sidebar) return;
      var isOpen = sidebar.classList.contains("mobile-filter-open");
      if (isOpen) {
        sidebar.classList.remove("mobile-filter-open");
        if (btn) btn.classList.remove("active");
        if (btnText) btnText.textContent = "Bộ lọc & Danh mục";
      } else {
        sidebar.classList.add("mobile-filter-open");
        if (btn) btn.classList.add("active");
        if (btnText) btnText.textContent = "Ẩn bộ lọc";
      }
    }
    window.toggleMobileFilter = toggleMobileFilter;

    function changeAllProdPage(p) {
      allProdCurrentPage = p;
      renderAllProductsPage();
      const el = document.getElementById("viewAllProducts");
      if (el) el.scrollIntoView({ behavior: "smooth" });
    }
    window.changeAllProdPage = changeAllProdPage;

    function renderSingleCardListMode(p) {
      const displaySold = (typeof getRealisticProductSold === "function") ? getRealisticProductSold(p).toLocaleString("vi-VN") : (p.buffSold || p.sold || 0);
      const totalStock = typeof getProductStockCount === "function" ? getProductStockCount(p) : (p.stock !== undefined ? p.stock : 0);
      let stockText = totalStock > 99 ? '99+' : totalStock;
      if (totalStock === 0) stockText = '<span style="color:#f59e0b; font-weight:700;"><i class="fa-solid fa-clock"></i> Đặt trước</span>';
      else if (totalStock < 5) stockText = '<span style="color:#f59e0b; font-weight:700;">Sắp hết (' + totalStock + ')</span>';

      return '<div class="product-card product-card-list-mode" onclick="openProductDetailById(&quot;' + p.id + '&quot;)" style="display:flex; flex-direction:row; align-items:center; gap:16px; padding:12px 16px; background:#0b111e; border:1px solid #1e293b; border-radius:10px; cursor:pointer; margin-bottom:10px; transition:border 0.2s;">' +
        '<div style="width:84px; height:84px; flex-shrink:0; border-radius:8px; overflow:hidden; background:#070a12; border:1px solid #1e293b;">' +
          '<img src="' + p.image + '" alt="' + escapeHtml(p.name) + '" style="width:100%; height:100%; object-fit:cover;" onerror="this.onerror=null; if(typeof resolveProductImage===\'function\'){ this.src=resolveProductImage({id:\'' + (p.id || '') + '\', name:\'' + escapeHtml(p.name).replace(/'/g, "\\'") + '\', category:\'' + escapeHtml(p.category || '').replace(/'/g, "\\'") + '\'}); }" />' +
        '</div>' +
        '<div style="flex:1; min-width:0;">' +
          '<div style="font-size:0.95rem; font-weight:700; color:#fff; margin-bottom:6px; line-height:1.3; display:flex; align-items:center; gap:8px;">' +
            '' +
            '<a href="?prod=' + encodeURIComponent(p.id) + '&view=viewProductDetail" target="_blank" onclick="if(!event.ctrlKey && !event.metaKey && event.button === 0){ event.preventDefault(); event.stopPropagation(); openProductDetailById(\'' + p.id + '\'); }" style="color:#fff; text-decoration:none;" onmouseover="this.style.color=\'#10b981\'" onmouseout="this.style.color=\'#fff\'"><span>' + escapeHtml(p.name) + '</span></a>' +
          '</div>' +
          '<div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:6px;">' +
            '<span style="font-size:0.75rem; color:#10b981; background:rgba(16,185,129,0.1); padding:2px 8px; border-radius:4px; font-weight:700;">' +
              '<i class="fa-solid fa-dollar-sign"></i> HOA HỒNG: ' + (p.commission || '10%') +
            '</span>' +
            '<span style="font-size:0.75rem; color:#94a3b8;"><i class="fa-solid fa-tag"></i> ' + escapeHtml(p.category || 'MMO') + '</span>' +
          '</div>' +
          '<div style="font-size:0.75rem; color:#64748b;">' +
            '<span>Đã bán: ' + displaySold + '</span> | <span>Kho: ' + stockText + '</span>' +
          '</div>' +
        '</div>' +
        '<div style="text-align:right; flex-shrink:0; display:flex; flex-direction:column; align-items:flex-end; gap:8px;">' +
          '<span style="font-size:1.15rem; font-weight:800; color:#10b981;">' + ((typeof getProductPriceDisplay === "function") ? getProductPriceDisplay(p) : formatVND(p.price)) + '</span>' +
          '<span style="font-size:0.75rem; color:#f59e0b; background:rgba(245,158,11,0.1); padding:2px 6px; border-radius:4px; font-weight:700;"><i class="fa-solid fa-star"></i> ' + (p.rating || '4.8') + '</span>' +
          '<button class="btn-primary" style="padding:6px 16px; font-size:0.8rem; border-radius:6px; background:#0284c7; color:#fff; border:none; cursor:pointer; font-weight:700;">MUA NGAY</button>' +
        '</div>' +
      '</div>';
    }
    window.renderSingleCardListMode = renderSingleCardListMode;

    function renderAllProductsPage() {
      // 1. Render Categories sidebar
      const catContainer = document.getElementById("allProdCategoryList");
      if (catContainer) {
        const allProds = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products : []);
        const cats = (MOCK_DATA && MOCK_DATA.categories) ? MOCK_DATA.categories : ["Tất cả"];

        let catHtml = '';
        cats.forEach(function(cat) {
          const isAll = (cat === "Tất cả");
          const count = isAll ? allProds.length : allProds.filter(function(p) { return (p.category || "").toLowerCase() === cat.toLowerCase(); }).length;
          const isActive = (allProdCurrentCat === cat);

          const activeStyle = isActive 
            ? 'background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); font-weight:700;' 
            : 'background:transparent; color:#cbd5e1; border:1px solid transparent;';
          const badgeStyle = isActive 
            ? 'background:#ef4444; color:#fff;' 
            : 'background:#1e293b; color:#94a3b8;';

          catHtml += '<div onclick="setAllProdCategory(&quot;' + escapeHtml(cat) + '&quot;)" style="display:flex; justify-content:space-between; align-items:center; padding:7px 12px; border-radius:6px; font-size:0.83rem; cursor:pointer; transition:all 0.2s; ' + activeStyle + '">' +
            '<span>' + escapeHtml(cat) + '</span>' +
            '<span style="font-size:0.72rem; padding:2px 7px; border-radius:4px; font-weight:700; ' + badgeStyle + '">' + count + '</span>' +
          '</div>';
        });
        catContainer.innerHTML = catHtml;
      }

      // 2. Filter Products
      const container = document.getElementById("allProductsGrid");
      if (!container) return;

      let list = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? [...MOCK_DATA.products] : []);

      const q = (document.getElementById("allProdSearchInp")?.value || "").trim();
      if (q) {
        list = list.filter(function(p) {
          return (typeof matchProductQuery === "function") ? matchProductQuery(p, q) : ((p.name || "").toLowerCase().includes(q.toLowerCase()) || (p.category || "").toLowerCase().includes(q.toLowerCase()));
        });
      }

      if (allProdCurrentCat && allProdCurrentCat !== "Tất cả") {
        list = list.filter(function(p) { return (p.category || "").toLowerCase().includes(allProdCurrentCat.toLowerCase()); });
      }

      const minP = parseFloat(document.getElementById("allProdPriceMin")?.value) || 0;
      const maxP = parseFloat(document.getElementById("allProdPriceMax")?.value) || 0;
      if (minP > 0) {
        list = list.filter(function(p) { return (Number(p.price) || 0) >= minP; });
      }
      if (maxP > 0) {
        list = list.filter(function(p) { return (Number(p.price) || 0) <= maxP; });
      }

      const inStockOnly = document.getElementById("allProdInStockOnly")?.checked;
      if (inStockOnly) {
        list = list.filter(function(p) { return (p.stock === undefined || Number(p.stock) > 0); });
      }

      const countBadge = document.getElementById("allProdCountBadge");
      if (countBadge) countBadge.innerText = list.length + " kết quả";

      // 3. Sort
      if (allProdCurrentSort === "bestseller") {
        list.sort(function(a, b) { return (b.sold || 0) - (a.sold || 0); });
      } else if (allProdCurrentSort === "price_asc") {
        list.sort(function(a, b) { return (a.price || 0) - (b.price || 0); });
      } else if (allProdCurrentSort === "price_desc") {
        list.sort(function(a, b) { return (b.price || 0) - (a.price || 0); });
      } else if (allProdCurrentSort === "newest") {
        list.reverse();
      }

      if (list.length === 0) {
        container.innerHTML = '<div style="grid-column: 1/-1; text-align:center; padding:60px 20px; color:#64748b;">' +
          '<i class="fa-solid fa-box-open" style="font-size:3rem; margin-bottom:12px; display:block; color:#334155;"></i>' +
          '<p style="font-size:1rem; color:#94a3b8;">Không tìm thấy sản phẩm nào phù hợp với bộ lọc.</p>' +
          '<button type="button" onclick="resetAllProdFilter()" style="margin-top:10px; background:#131d2e; border:1px solid #1e293b; color:#38bdf8; padding:8px 16px; border-radius:6px; cursor:pointer;">Đặt lại bộ lọc</button>' +
        '</div>';
        const pag = document.getElementById("allProductsPagination");
        if (pag) pag.innerHTML = "";
        return;
      }

      // 4. Pagination
      const totalPages = Math.ceil(list.length / ALL_PROD_PAGE_SIZE);
      if (allProdCurrentPage > totalPages) allProdCurrentPage = totalPages;
      if (allProdCurrentPage < 1) allProdCurrentPage = 1;

      const startIndex = (allProdCurrentPage - 1) * ALL_PROD_PAGE_SIZE;
      const pageProds = list.slice(startIndex, startIndex + ALL_PROD_PAGE_SIZE);

      if (allProdViewMode === "list") {
        container.className = "all-prods-list";
        container.style.display = "flex";
        container.style.flexDirection = "column";
        container.style.gap = "10px";
        container.innerHTML = pageProds.map(function(p) { return renderSingleCardListMode(p); }).join("");
      } else {
        container.className = "all-prods-grid";
        container.style.display = "";
        container.style.flexDirection = "";
        container.style.gridTemplateColumns = "";
        container.style.gap = "";
        container.innerHTML = pageProds.map(function(p) { return renderSingleCard(p, false); }).join("");
      }

      if (typeof renderPaginationUI === "function") {
        renderPaginationUI("allProductsPagination", allProdCurrentPage, list.length, "changeAllProdPage", ALL_PROD_PAGE_SIZE);
      }
    }
