    window.handleOpenOrderDetailsFromChat = handleOpenOrderDetailsFromChat;

    // Hàm sao chép văn bản phần tử trực tiếp
    function copyDirectElementText(elId) {
      const el = document.getElementById(elId);
      if (!el) return;
      const text = el.value || el.innerText || "";
      if (!text) return;
      if (navigator.clipboard) {
        navigator.clipboard.writeText(text).then(() => showToast("Đã sao chép vào bộ nhớ tạm!", "success")).catch(() => {});
      } else {
        el.select();
        document.execCommand("copy");
        showToast("Đã sao chép vào bộ nhớ tạm!", "success");
      }
    }
    window.copyDirectElementText = copyDirectElementText;


    // [VARIANT INVENTORY]: Hàm getVariantStockKey & getVariantStockCount đã được định nghĩa chuẩn tại phần đầu script.

    // [TURSO CLOUD WAREHOUSE & SSOT]: Đọc danh sách tài khoản trực tiếp từ Turso Database
    async function handleStockVariantChange() {
      const select = document.getElementById("admStockProductSelect");
      const varSelect = document.getElementById("admStockVariantSelect");
      if (!select) return;
      const prodId = select.value;
      if (!prodId) return;

      const prod = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(prodId)) : null;
      if (!prod) return;

      const hasVars = Array.isArray(prod.variants) && prod.variants.length > 0;
      const vVal = hasVars ? ((varSelect && varSelect.value !== undefined && varSelect.value !== "") ? varSelect.value : "0") : null;

      const countLabel = document.getElementById("admStockCountLabel");
      const targetBadge = document.getElementById("admStockVariantBadge");
      const countDisp = document.getElementById("admStockCountDisplay");
      const currentView = document.getElementById("admStockCurrentView");
      const warningBox = document.getElementById("admStockLowWarning");

      const targetProdName = document.getElementById("admStockTargetProdName");
      const targetVarName = document.getElementById("admStockTargetVarName");
      if (targetProdName) targetProdName.innerText = prod.name || prod.id;

      if (hasVars && prod.variants[vVal]) {
        const vObj = prod.variants[vVal];
        if (countLabel) countLabel.innerText = "Tồn kho biến thể " + (Number(vVal) + 1) + ":";
        if (targetBadge) {
          targetBadge.innerText = vObj.name;
          targetBadge.style.background = "rgba(16,185,129,0.2)";
          targetBadge.style.color = "#34d399";
        }
        if (targetVarName) {
          targetVarName.innerText = vObj.name || ("Biến thể " + (Number(vVal) + 1));
          targetVarName.style.background = "rgba(56,189,248,0.2)";
          targetVarName.style.color = "#38bdf8";
        }
      } else {
        if (countLabel) countLabel.innerText = "Số lượng trong kho hiện tại:";
        if (targetBadge) {
          targetBadge.innerText = "Kho chính";
          targetBadge.style.background = "rgba(99,102,241,0.2)";
          targetBadge.style.color = "#c7d2fe";
        }
        if (targetVarName) {
          targetVarName.innerText = "Kho chính";
          targetVarName.style.background = "rgba(99,102,241,0.2)";
          targetVarName.style.color = "#c7d2fe";
        }
      }

      // ƯU TIÊN 100%: NẾU ĐÃ CẤU HÌNH TURSO DATABASE, ĐỌC TRỰC TIẾP TỪ TURSO
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        if (currentView) currentView.placeholder = "⏳ Đang tải tài khoản từ Turso Database...";
        try {
          const accounts = await TURSO_CLIENT.getAvailableAccounts(prodId, vVal);
          const count = accounts.length;

          if (currentView) {
            currentView.value = accounts.join("\n");
            currentView.placeholder = "Mỗi dòng 1 tài khoản (Định dạng: user|pass|2fa|...)";
          }
          if (countDisp) {
            countDisp.innerText = count + " acc";
            if (count === 0) countDisp.style.color = "#ef4444";
            else if (count < 5) countDisp.style.color = "#f59e0b";
            else countDisp.style.color = "#10b981";
          }

          // Đồng bộ bộ nhớ local và biến thể
          if (hasVars && prod.variants && prod.variants[vVal]) {
            prod.variants[vVal].accounts = accounts;
            prod.variants[vVal].stock = count;
            prod.stock = prod.variants.reduce((s, v) => s + (Number(v.stock) || 0), 0);
          } else {
            prod.accounts = accounts;
            prod.stock = count;
          }

          if (typeof updateVariantSelectForProduct === "function") {
            updateVariantSelectForProduct(prodId);
            const varSelAfter = document.getElementById("admStockVariantSelect");
            if (varSelAfter && vVal !== null) varSelAfter.value = vVal;
          }

          if (typeof saveProductsToStorage === "function") saveProductsToStorage();
          if (typeof recordProductVariants === "function") recordProductVariants(prodId, prod.variants, prod.name);
          refreshAllShopStockUI(prodId);

          if (warningBox) {
            if (count === 0) {
              warningBox.style.display = "flex";
              warningBox.style.borderColor = "rgba(239,68,68,0.4)";
              warningBox.style.background = "rgba(239,68,68,0.12)";
              warningBox.style.color = "#ef4444";
              warningBox.innerHTML = hasVars 
                ? "<i class='fa-solid fa-triangle-exclamation'></i> <span>Kho biến thể này đang <strong>HẾT HÀNG (0 acc trên Turso)!</strong> Vui lòng nạp thêm tài khoản vào ô bên trên.</span>"
                : "<i class='fa-solid fa-triangle-exclamation'></i> <span>Kho sản phẩm đang <strong>HẾT HÀNG (0 acc trên Turso)!</strong> Vui lòng nạp thêm tài khoản vào ô bên trên.</span>";
            } else if (count < 5) {
              warningBox.style.display = "flex";
              warningBox.style.borderColor = "rgba(245,158,11,0.4)";
              warningBox.style.background = "rgba(245,158,11,0.12)";
              warningBox.style.color = "#f59e0b";
              warningBox.innerHTML = "<i class='fa-solid fa-triangle-exclamation'></i> <span>Cảnh báo: Kho chỉ còn <strong>" + count + " acc</strong> trên Turso Database!</span>";
            } else {
              warningBox.style.display = "none";
            }
          }
        } catch(tursoLoadErr) {
          console.warn("Turso load failed, falling back to local warehouse:", tursoLoadErr);
          if (currentView) currentView.placeholder = "Đang dùng kho nội bộ (Turso API tạm thời ngoại tuyến)";
        }

        // FALLBACK KHO NỘI BỘ (Khi Turso lỗi hoặc chưa cấu hình)
        const localAccounts = (typeof MMO_WAREHOUSE !== "undefined") ? MMO_WAREHOUSE.getAvailable(prodId, vVal) : [];
        let effectiveCount = localAccounts.length;
        if (effectiveCount === 0 && prod) {
          const vObj = (hasVars && prod.variants && prod.variants[vVal]) ? prod.variants[vVal] : prod;
          if (typeof vObj.stock === "number" && vObj.stock > 0) effectiveCount = vObj.stock;
        }

        if (countDisp) {
          countDisp.innerText = effectiveCount + " acc";
          if (effectiveCount === 0) countDisp.style.color = "#ef4444";
          else if (effectiveCount < 5) countDisp.style.color = "#f59e0b";
          else countDisp.style.color = "#10b981";
        }

        if (currentView) {
          if (localAccounts.length > 0) {
            currentView.value = localAccounts.join("\n");
          }
          currentView.placeholder = "Mỗi dòng 1 tài khoản (Định dạng: user|pass|2fa|...)";
        }

        if (hasVars && prod.variants && prod.variants[vVal]) {
          if (localAccounts.length > 0) prod.variants[vVal].accounts = localAccounts;
          prod.variants[vVal].stock = effectiveCount;
        }

        renderSoldStockAccountsView(prodId, vVal);
        return;
      }

      // FALLBACK KHO NỘI BỘ (Khi chưa cấu hình Turso)
      const accounts = MMO_WAREHOUSE.getAvailable(prodId, vVal);
      const count = accounts.length;

      if (countDisp) {
        countDisp.innerText = count + " acc";
        if (count === 0) countDisp.style.color = "#ef4444";
        else if (count < 5) countDisp.style.color = "#f59e0b";
        else countDisp.style.color = "#10b981";
      }

      if (currentView) currentView.value = accounts.join("\n");
      renderSoldStockAccountsView(prodId, vVal);

      if (warningBox) {
        if (count === 0) {
          warningBox.style.display = "flex";
          warningBox.style.borderColor = "rgba(239,68,68,0.4)";
          warningBox.style.background = "rgba(239,68,68,0.12)";
          warningBox.style.color = "#ef4444";
          warningBox.innerHTML = hasVars 
            ? "<i class='fa-solid fa-triangle-exclamation'></i> <span>Kho biến thể này đang <strong>HẾT HÀNG!</strong> Vui lòng nạp thêm tài khoản vào ô bên trên.</span>"
            : "<i class='fa-solid fa-triangle-exclamation'></i> <span>Kho sản phẩm đang <strong>HẾT HÀNG!</strong> Vui lòng nạp thêm tài khoản vào ô bên trên.</span>";
        } else if (count < 5) {
          warningBox.style.display = "flex";
          warningBox.style.borderColor = "rgba(245,158,11,0.4)";
          warningBox.style.background = "rgba(245,158,11,0.12)";
          warningBox.style.color = "#f59e0b";
          warningBox.innerHTML = "<i class='fa-solid fa-triangle-exclamation'></i> <span>Cảnh báo: Kho biến thể chỉ còn <strong>" + count + " acc!</strong></span>";
        } else {
          warningBox.style.display = "none";
        }
      }
    }
    window.handleStockVariantChange = handleStockVariantChange;

    // [UNIFIED WAREHOUSE & TURSO]: HIỂN THỊ LỊCH SỬ TÀI KHOẢN ĐÃ BÁN
    async function renderSoldStockAccountsView(prodId, variantVal) {
      const soldView = document.getElementById("admStockSoldCurrentView");
      const soldCountEl = document.getElementById("admStockSoldCountDisplay");
      if (!soldView && !soldCountEl) return;

      // Ưu tiên đọc trực tiếp từ Turso Database
      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        try {
          const soldItems = await TURSO_CLIENT.fetchSoldAccounts(prodId, variantVal);
          if (soldCountEl) soldCountEl.innerText = soldItems.length;
          if (soldView) {
            if (soldItems.length === 0) {
              soldView.value = "";
              soldView.placeholder = "Chưa có tài khoản nào được bán ra từ mục này trên Turso.";
            } else {
              soldView.value = soldItems.map(it => {
                let d = "Đã giao";
                if (it.sold_at) {
                  const num = Number(it.sold_at);
                  const dt = !isNaN(num) ? new Date(num) : new Date(it.sold_at);
                  d = (dt instanceof Date && !isNaN(dt.getTime())) ? dt.toLocaleString("vi-VN") : String(it.sold_at);
                }
                const o = it.order_id ? (" [Đơn: " + it.order_id + "]") : "";
                const isEx = it.type === "WARRANTY_EXCHANGE" || (it.note && it.note.includes("Bảo hành")) || String(it.order_id || "").includes("EXCHANGE");
                const tag = isEx ? " (Bảo hành 1-đổi-1: " : " (Bán: ";
                return (it.account || "") + "  --- " + tag + d + o + ")";
              }).join("\n");
            }
          }
          return;
        } catch(tursoSoldErr) {
          console.error("Lỗi lấy lịch sử bán Turso:", tursoSoldErr);
        }
      }

      // Fallback local
      const soldItems = MMO_WAREHOUSE.getSold(prodId, variantVal);
      if (soldCountEl) soldCountEl.innerText = soldItems.length;

      if (soldView) {
        if (soldItems.length === 0) {
          soldView.value = "";
          soldView.placeholder = "Chưa có tài khoản nào được bán ra từ mục này.";
        } else {
          soldView.value = soldItems.map(it => {
            let d = "Đã giao";
            if (it.sold_at) {
              const num = Number(it.sold_at);
              const dt = !isNaN(num) ? new Date(num) : new Date(it.sold_at);
              d = (dt instanceof Date && !isNaN(dt.getTime())) ? dt.toLocaleString("vi-VN") : String(it.sold_at);
            }
            const o = it.order_id ? (" [Đơn: " + it.order_id + "]") : "";
            const isEx = it.type === "WARRANTY_EXCHANGE" || (it.note && it.note.includes("Bảo hành")) || String(it.order_id || "").includes("EXCHANGE");
            const tag = isEx ? " (Bảo hành 1-đổi-1: " : " (Bán: ";
            return (it.account || "") + "  --- " + tag + d + o + ")";
          }).join("\n");
        }
      }
    }
    window.renderSoldStockAccountsView = renderSoldStockAccountsView;

    function copySoldStockAccounts() {
      const soldView = document.getElementById("admStockSoldCurrentView");
      if (!soldView || !soldView.value.trim()) {
        showToast("Không có tài khoản đã bán nào để sao chép!", "warning");
        return;
      }
      copyTextDirect(soldView.value);
      showToast("Đã sao chép danh sách tài khoản đã bán!", "success");
    }
    window.copySoldStockAccounts = copySoldStockAccounts;

    // [DIRECT PRODUCT-INVENTORY & TURSO]: XÓA LỊCH SỬ TÀI KHOẢN ĐÃ BÁN
    async function clearSoldStockHistory() {
      const select = document.getElementById("admStockProductSelect");
      const varSelect = document.getElementById("admStockVariantSelect");
      if (!select) return;
      const prodId = select.value;
      if (!prodId) return;

      const vVal = varSelect ? varSelect.value : "ALL";

      if (typeof TURSO_CLIENT !== "undefined" && TURSO_CLIENT.isConfigured()) {
        try {
          await TURSO_CLIENT.clearSoldAccounts(prodId, vVal);
          const soldView = document.getElementById("admStockSoldCurrentView");
          if (soldView) {
            soldView.value = "";
            soldView.placeholder = "Chưa có tài khoản nào được bán ra từ mục này trên Turso.";
          }
          const soldCountEl = document.getElementById("admStockSoldCountDisplay");
          if (soldCountEl) soldCountEl.innerText = "0";
          showToast("🗑️ Đã xóa toàn bộ lịch sử tài khoản đã bán trên Turso Database!", "success");
          return;
        } catch(tursoClearSoldErr) {
          console.error("Lỗi xóa lịch sử bán Turso:", tursoClearSoldErr);
          showToast("Lỗi xóa lịch sử Turso: " + tursoClearSoldErr.message, "danger");
          return;
        }
      }

      MMO_WAREHOUSE.clearSold(prodId, vVal);
      renderSoldStockAccountsView(prodId, vVal);
      showToast("🗑️ Đã xóa toàn bộ lịch sử tài khoản đã bán!", "success");
    }
    window.clearSoldStockHistory = clearSoldStockHistory;


    function updateVariantSelectForProduct(prodId) {
      const varWrap = document.getElementById("admStockVariantWrap");
      const varSelect = document.getElementById("admStockVariantSelect");
      if (!varWrap || !varSelect) return;

      const prod = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.find(p => String(p.id) === String(prodId)) : null;
      if (!prod || !prod.variants || prod.variants.length === 0) {
        varWrap.style.display = "none";
        varSelect.innerHTML = "<option value='0'>Kho sản phẩm</option>";
        return;
      }

      varWrap.style.display = "block";
      const map = getProductStocksMap();

      // Tự động chuyển giao kho cũ sang biến thể 0 nếu biến thể 0 chưa có dữ liệu riêng
      let isCleared = false;
      try {
        const clm = JSON.parse(localStorage.getItem("mmo_manually_cleared_products") || "{}");
        if (clm[prodId] || clm[getVariantStockKey(prodId, 0)]) isCleared = true;
      } catch(e) {}
      const v0Key = getVariantStockKey(prodId, 0);
      if (!isCleared && Array.isArray(map[prodId]) && map[prodId].length > 0 && map[v0Key] === undefined) {
        map[v0Key] = map[prodId];
        saveProductStocksMap(map);
      }

      const prevVal = varSelect.value;
      let optionsHtml = "<option value='ALL'>📦 Tất cả biến thể (Toàn bộ kho sản phẩm)</option>";
      prod.variants.forEach(function(v, idx) {
        const vKey = getVariantStockKey(prodId, idx);
        const vStock = (typeof getVariantStockCount === "function") ? getVariantStockCount(prod, idx) : ((map[vKey] && Array.isArray(map[vKey])) ? map[vKey].length : 0);
        let tag = "(" + vStock + " acc)";
        if (vStock === 0) tag = "❌ [HẾT HÀNG]";
        else if (vStock < 5) tag = "⚠️ [" + vStock + " acc]";
        optionsHtml += "<option value='" + idx + "'>Biến thể " + (idx + 1) + ": " + escapeHtml(v.name) + " " + tag + " - " + formatVND(v.price) + "</option>";
      });

      if (varSelect.innerHTML !== optionsHtml) {
        varSelect.innerHTML = optionsHtml;
        if (prevVal !== undefined && prevVal !== "" && prod.variants[prevVal]) {
          varSelect.value = prevVal;
        } else if (prod.variants.length > 0) {
          varSelect.value = "0";
        }
      }
    }
    window.updateVariantSelectForProduct = updateVariantSelectForProduct;

    // =========================================================================
    // TÍCH HỢP API & TÀI LIỆU API MUA HÀNG CHO KHÁCH & ĐỐI TÁC RESELLER
    // =========================================================================
    function renderProductApiIntegration() {
      const p = currentSelectedProduct;
      if (!p) return;
      const codeEl = document.getElementById("dtlApiProdCode");
      if (codeEl) codeEl.innerText = p.id || "";
      const curVIdx = (typeof currentSelectedVariantIndex === "number") ? currentSelectedVariantIndex : 0;
      
      const jsonPayloadEl = document.getElementById("dtlApiJsonPayload");
      if (jsonPayloadEl) {
        jsonPayloadEl.innerText = JSON.stringify({
          apiKey: "YOUR_API_KEY",
          productId: p.id || "PROD_ID",
          variantIndex: curVIdx,
          quantity: 1
        }, null, 2);
      }

      const curlEl = document.getElementById("dtlApiCurlCode");
      if (curlEl) {
        curlEl.innerText = 'curl -X POST "https://mmo-shop-api.khotaikhoanso-net.workers.dev/api/orders/checkout" \\\n  -H "Content-Type: application/json" \\\n  -d \'{"apiKey":"YOUR_API_KEY","productId":"' + (p.id || 'PROD_ID') + '","variantIndex":' + curVIdx + ',"quantity":1}\'';
      }
    }
    window.renderProductApiIntegration = renderProductApiIntegration;

    function copyApiCode(elementId, btn) {
      const el = document.getElementById(elementId);
      if (!el) return;
      const text = el.innerText || el.textContent;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function() {
          if (typeof showToast === "function") showToast("✅ Đã sao chép mã thành công!", "success");
          if (btn) {
            const oldHtml = btn.innerHTML;
            btn.innerHTML = "<i class='fa-solid fa-check'></i> Đã chép";
            setTimeout(function() { btn.innerHTML = oldHtml; }, 2000);
          }
        }).catch(function() {
          fallbackCopyText(text, btn);
        });
      } else {
        fallbackCopyText(text, btn);
      }
    }
    window.copyApiCode = copyApiCode;

    function fallbackCopyText(text, btn) {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
        if (typeof showToast === "function") showToast("✅ Đã sao chép thành công!", "success");
        if (btn) {
          const oldHtml = btn.innerHTML;
          btn.innerHTML = "<i class='fa-solid fa-check'></i> Đã chép";
          setTimeout(function() { btn.innerHTML = oldHtml; }, 2000);
        }
      } catch(e) {
        if (typeof showToast === "function") showToast("⚠️ Vui lòng bôi đen và bấm Ctrl+C để sao chép.", "warning");
      }
      document.body.removeChild(ta);
    }

    function openApiDocsModal() {
      const modal = document.getElementById("apiDocsModal");
      if (modal) {
        modal.style.display = "flex";
        modal.style.zIndex = "9999999";
        document.body.style.overflow = "hidden";
      }
    }
    window.openApiDocsModal = openApiDocsModal;

    function closeApiDocsModal() {
      const modal = document.getElementById("apiDocsModal");
      if (modal) {
        modal.style.display = "none";
        document.body.style.overflow = "";
      }
    }
    window.closeApiDocsModal = closeApiDocsModal;

